WITH payload AS (SELECT $archive_payload$[{"id":"bc386281-a931-547d-933a-fdc4e4f70d80","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حشيش وحبوب محظورة بقصد االجتار وتعاطيها- إثبات بالشهادة -إدانة -إقامة حد املسكر -تعزير بالسجن واجللد والغرامة -إبعاد عن الباد -صرف نظر .","document_number":"3414946","case_number":"33678573","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/27","year":"1434","subject":"مخدرات -حيازة حشيش وحبوب محظورة بقصد االجتار وتعاطيها- إثبات بالشهادة -إدانة -إقامة حد املسكر -تعزير بالسجن واجللد والغرامة -إبعاد عن الباد -صرف نظر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 3414946:‬تاريخه ‪1433/11/27:‬هـ‬\n                       ‫رقم الدعوى ‪33678573:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 3431520‬تاريخه‪1434/02/06 :‬هـ‬\n\n\n      ‫مخــدرات‪ -‬حيــازة حشــيش وحبوب محظــورة بقصد االجتار وتعاطيها‪-‬‬\n      ‫إثبــات بالشــهادة‪ -‬إدانــة ‪ -‬إقامــة حــد املســكر ‪ -‬تعزيــر بالســجن واجللــد‬\n                                  ‫والغرامــة ‪ -‬إبعــاد عــن البــاد ‪ -‬صــرف نظــر ‪.‬‬\n\n\n\n\n      ‫الفقــرة (‪ )1‬مــن املــادة (‪ )38‬والفقــرة (‪ )2‬مــن املــادة(‪ )56‬مــن نظــام‬\n                                     ‫مكافحــة املخــدرات واملؤثــرات العقليــة‪.‬‬\n\n\n\n      ‫دعــوى جزائيــة عامــة ضــد املدعــى عليــه تتضمــن طلــب إثبــات إدانتــه‬\n      ‫بحيــازة احلشــيش املخــدر واحلبــوب احملظــورة بقصــد االجتــار والتعاطــي‬\n      ‫وترويجهــا وتعاطيــه لهــا يف الســابق‪ ،‬واحلكــم عليــه بعقوبــة الســجن‬\n      ‫واجللــد والغرامــة واملصــادرة واإلبعــاد عــن البــاد طبقــا لنظــام مكافحــة‬\n      ‫املخــدرات واملؤثــرات العقليــة‪ ،‬مت تفتيــش غرفتــه يف مقــر عملــه بإحــدى‬\n      ‫الــورش بعــد ورود معلومــات عــن ترويجــه للمخــدرات فعثــر فيهــا علــى‬\n      ‫الكميــة املضبوطــة مــن احلشــيش املخــدر واحلبــوب احملظــورة‪ ،‬أثبــت‬\n      ‫التقريــر الكيمــاوي الشــرعي إيجابيــة العينــة املرســلة للحشــيش املخــدر‬\n      ‫واإلمفيتامــن‪ ،‬أقــر أمــام احملكمــة بحيــازة مــا ضبــط معــه بقصــد‬\n      ‫التعاطــي وأنكــر قصــد االجتــار‪ ،‬طلبــت احملكمــة مــن املدعــي العــام‬\n\n‫‪253‬‬\n\f‫تقــدمي بيناتــه وقــررت ســماع شــهادة شــهود محضــر القبــض فشــهدوا مبــا‬\n‫يثبــت الدعــوى‪ ،‬قضــت احملكمــة بإدانــة املدعــى عليــه بحيــازة احلشــيش‬\n‫املخــدر واحلبــوب احملظــورة بقصــد الترويــج وتعاطيــه لهمــا وقــررت‬\n‫جلــده ثمانــن جلــدة حــد املســكر علنــا يف مــكان عــام وســجنه ملــدة‬\n‫أربــع ســنوات وجلــده أربعمائــة جلــدة مفرقــة علــى ثمــان دفعــات وتغرميــه‬\n‫مبلــغ خمســة آالف ريــال وإبعــاده عــن البــاد بعــد انتهــاء محكوميتــه‬\n‫كمــا قضــت بصــرف النظــر عــن طلــب املدعــي العــام مصــادرة أجهــزة‬\n‫اجلــوال العائــدة لــه‪ ،‬قنــع املدعــى عليــه باحلكــم وعــارض املدعــي العــام‬\n             ‫عليه‪،‬قــررت محكمــة االســتئناف املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد لــدي أنــا‪ ....‬القاضــي باحملكمــة اجلزائيــة‬\n‫بالقطيــف بنــاء علــى املعاملــة احملالــة إلــي مــن فضيلــة الرئيــس برقــم‬\n‫‪ 33678573‬يف‪1433/11/27‬ه ـ والــواردة بكتــاب رئيــس دائــرة‬\n‫التحقيــق واالدعــاء العــام مبحافظــة القطيــف ذي الرقم ه ـ ق‪3324/2/4‬‬\n‫يف ‪1433/11/27‬ه حضــر املدعــي العــام مبوجــب كتــاب التكليــف‬\n‫رقــم وادعــى علــى احلاضــر معــه مينــي اجلنســية واملقيــم يف البــاد مبوجــب‬\n‫ال يف دعواه إنه بتاريخ ‪1433/10/25‬هـ توفرت‬           ‫رخصة اإلقامة رقم قائ ً‬\n‫معلومــات لرجــال مكافحــة املخــدرات عــن قيــام املدعــى عليــه بترويــج‬\n‫احلشــيش املخــدر واحلبــوب احملظــورة ويســتخدم جوالــه ذي الرقــم (‪)....‬‬\n‫ومت الرصــد بعــد املراقبــة ألشــخاص مشــبوهني يتــرددون مبقــر عملــه‬\n‫بإحــدى ورش صفــوي فتــم أخــذ اإلذن بتفتيــش مقــره وبدخــول غرفتــه‬\n‫التــي بالورشــة عثــر علــى قطعتــن ســمراء اللــون بلــغ وزنهــا (‪)367.6‬‬\n\n                                                                                   ‫‪254‬‬\n\f      ‫ثالثمائــة وســبعة وســتني جرامـ ًا وســتة مــن العشــرة مــن اجلــرام كمــا عثــر‬\n      ‫علــى (‪ )1700‬ألــف وســبعمائة حبــة وعلــى جوالــن أحدهمــا ‪ ....‬واآلخــر‬\n      ‫مــن نــوع ‪ ....‬ويحمــل الرقــم املصنعــي (‪ )....‬وأقــر أمــام الفرقــة القابضــة‬\n      ‫صحــة واقعــة الضبــط وأن مــا وجــد بحوزتــه عائــد لــه لغــرض الترويــج‬\n      ‫وأنــه يقــوم بترويــج املخــدرات منــذ فتــرة داخــل صفــوى وأثبــت التقريــر‬\n      ‫الكيمــاوي الشــرعي الصــادر مــن املركــز اإلقليمــي ملراقبــة الســموم‬\n      ‫باملنطقــة الشــرقية رقــم (‪ 3895‬ك ش )وتاريــخ ‪1433/11/3‬ه ـ إيجابيــة‬\n      ‫العينتــن ملــادة احلشــيش املخــدر وإيجابيــة احلبــوب ملــادة اإلمفيتامــن وقــد‬\n      ‫انتهــى التحقيــق إلــى توجيــه االتهــام إليــه بحيــازة قطعتــن مــن احلشــيش‬\n      ‫املخــدر تزنــان (‪ )367.6‬ثالثمائــة وســبعة وســتني جرام ـ ًا وســتة مــن‬\n      ‫العشــرة مــن اجلــرام لقصــد االجتــار والتعاطــي وترويجــه املخــدرات يف‬\n      ‫الســابق وحيــازة مــا عــدده (‪ )1700‬ألــف وســبعمائة حبــة كبتاجــون‬\n      ‫مخــدر لقصــد االجتــار والتعاطــي وتعاطيــه احلشــيش املخــدر واحلبــوب‬\n      ‫احملظــورة وبالبحــث عمــا إذا كان لــه ســوابق لــم يعثــر لــه علــى ســوابق‬\n      ‫مســجله وحيــث إن مــا أقــدم عليــه املذكــور‪ ،‬وهــو بكامــل أهليتــه‬\n      ‫املعتبــرة شــرع ًا ‪ -‬فعــل محــرم ومعاقــب عليــه شــرع ًا ونظام ـ ًا لــذا أطلــب‬\n      ‫اآلتــي‪ :‬أوالً‪ :‬إثبــات مــا أســند إليــه وفــق الفقــرة رقــم (‪ )2‬مــن املــادة رقــم‬\n      ‫(‪ )3‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة واحلكــم عليــه‬\n      ‫مبــا يلــي‪ -1 :‬بعقوبــة الســجن واجللــد والغرامــة الــواردة يف الفقــرة (‪)1‬‬\n      ‫مــن املــادة (‪ )38‬مــن نظــام مكافحــة املخــدرات ووفق ـ ًا للفقــرة رقــم‬\n      ‫(‪ )1‬مــن املــادة(‪ )62‬مــن ذات النظــام بشــأن تطبيــق العقوبــة األشــد‬\n      ‫والتشــديد عليــه كــون مــن نــوع املضبــوط حبــوب منبهــه وفــق الفقــرة (‬\n      ‫‪/2‬ج) مــن املــادة رقــم (‪ )38‬مــن النظــام واســتنادا لبرقيــة صاحــب الســمو‬\n\n\n‫‪255‬‬\n\f‫امللكــي وزيــر الداخليــة رقــم (‪2/8346/5/1‬ش) وتاريــخ ‪1429/2/8‬ه ـ‬\n‫‪-2‬إبعــاده عــن البــاد وفــق الفقــرة رقــم (‪ )2‬مــن املــادة (‪)56‬مــن‬\n‫النظــام ثاني ـاً‪ :‬مصــادرة جهــازي اجلــوال املضبــوط معــه وشــريحته ذي‬\n‫الرقــم (‪ )....‬املوصــوف يف قــرار االتهــام الســتخدامها يف اجلرميــة وفقــا‬\n‫للفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )53‬مــن ذات النظــام و عــدم صــرف‬\n‫الشــريحة لنفــس املدعــى عليــه وفقــا لتعميــم صاحــب الســمو امللكــي‬\n‫وزيــر الداخليــة رقــم (‪ )9798‬وتاريــخ ‪1428/2/10-9‬ه ـ هــذا مــا ادعــى‬\n‫ا مــا ذكــره‬     ‫بــه وبعرضــه علــى املدعــى عليــه وبســؤاله عنــه أجــاب قائ ـ ً‬\n‫املدعــي العــام يف دعــواه ضــدي مــن اتهامــي بحيــازة احلشــيش وحيــازة‬\n‫العــدد الــذي ذكــر مــن احلبــوب احملظــورة لقصــد الترويــج واالجتــار‬\n‫غيــر صحيــح والصحيــح أنــي حزتــه لقصــد التعاطــي فقــط ومــا ذكــره‬\n‫مــن أنــي أتعاطــى احلشــيش املخــدر واحلبــوب احملظــورة صحيــح هــذا مــا‬\n‫ا الصحيــح مــا جــاء يف‬       ‫أجــاب بــه وبــرده علــى املدعــي العــام أفــاد قائ ـ ً‬\n‫ا‬‫دعــواي هــذا مــا أجــاب بــه وبســؤاله عــن بينتــه علــى طبقهــا أجــاب قائـ ً‬\n‫بينتــي مــا جــاء يف أوراق املعاملــة ولــدي شــهود الفرقــة القابضــة ومســتعد‬\n‫بإحضارهــم يف اجللســة القادمــة هــذا مــا أجــاب بــه وبالرجــوع إلــى أجوبــة‬\n‫املدعــى عليــه عــن أســئلة التحقيــق املرفقــة باملعاملــة باللفــة رقــم ‪ 10-9‬لــم‬\n‫أجــد فيــه مزيــد ًا علــى مــا أجــاب بــه املدعــى عليــه وبالرجــوع إلــى محضــر‬\n‫الضبــط والتفتيــش املــدون علــى الصحيفــة رقــم ‪ 12-11‬مــن امللــف‬\n‫املرفــق باملعاملــة باللفــة رقــم ‪ 1‬لــم أجــد فيــه مــا يعضــد دعــوى االدعــاء‬\n‫العــام ســوى إقــرار املدعــى عليــه أمــام الفرقــة القابضــة بــأن مــا حــازه إمنــا‬\n‫كان لغــرض الترويــج وقــد جــرى االطــاع علــى التقريــر الكيميائــي‬\n‫الشــرعي املشــار إليــه يف دعــوى املدعــي العــام ووجدتــه مطابق ـ ًا ملــا‬\n\n\n                                                                                           ‫‪256‬‬\n\f      ‫عطــف عليــه ويف جلســة أخــرى حضــر الطرفــان وبســؤال املدعــي العــام‬\n      ‫عــن بينتــه علــى طبــق دعــواه أحضــر للشــهادة وأدائهــا الســعودي بالســجل‬\n      ‫ا أشــهد هلل العظيــم‬     ‫املدنــي رقــم ‪ .........‬وبســؤاله عمــا لديــه شــهد قائ ـ ً‬\n      ‫بأنــه يــوم القبــض علــى املدعــى عليــه هــذا احلاضــر كنــت مــع الفرقــة‬\n      ‫وقــد ضبطــت مــع الفرقــة احلبــوب واحلشــيش املخــدر يف حــوزة املدعــى‬\n      ‫عليــه وأنــا مــن قــام بعدهــا وقــد اعتــرف أمامــي بــأن احلبــوب واحلشــيش لــه‬\n      ‫وأنــه يقــوم بتصريفهــا عــن طريــق البيــع هــذا مــا شــهد بــه كمــا أحضــر‬\n      ‫للشــهادة وأدائهــا ‪ ....‬الســعودي بالســجل املدنــي رقــم‪ ....‬وبســؤاله عمــا‬\n      ‫ا أشــهد هلل العظيــم أنــي كنــت ضمــن الفرقــة القابضــة‬          ‫لديــه شــهد قائـ ً‬\n      ‫التــي قبضــت علــى املدعــى عليــه هــذا احلاضــر وقــد حتــدث لــي شــخصي ًا‬\n      ‫وذكــر أن املضبوطــات لشــخص آخــر وأنــه يقــوم بترويجهــا لــه هــذا مــا‬\n      ‫ا‬ ‫شــهد بــه وبعــرض الشــاهدين وشــهادتهما علــى املدعــى عليــه أفــاد قائـ ً‬\n      ‫أمــا الشــهود فــا أعرفهمــا وأمــا شــهادتهما فغيــر صحيحــة والصحيــح‬\n      ‫مــا ذكرتــه يف إجابتــي عــن الدعــوى هــذا مــا أفــاد بــه وقــرر املدعــى‬\n      ‫ا لقــد تعاونــت مــع فرقــة مكافحــة املخــدرات وأرشــدتهم‬               ‫عليــه قائ ـ ً‬\n      ‫إلــى مروجــن للمخــدرات داخــل الســجن وخارجــه وقــد شــاركت يف‬\n      ‫ضبــط أحــد العمليــات هــذا مــا قــرره وقــرر كل واحــد مــن الشــاهدين‬\n      ‫ا إننــي أشــهد أنــه تعــاون معنــا يف ضبــط أحــد عمليــات الترويــج‬            ‫قائ ـ ً‬\n      ‫ا لقــد‬  ‫هــذا مــا قــرره كل واحــد منهمــا وأضــاف الشــاهد رامــي قائ ـ ً‬\n      ‫أرشــدنا إلــى كــذا منــزل يقــوم فيــه ذوه ببيــع املخــدر هــذا مــا أضافــه‬\n      ‫ا‬  ‫وبســؤال املدعــي العــام هــل لديــه مزيــد بينــة علــى مــا قــدم أجــاب قائـ ً‬\n      ‫إننــي أكتفــي مبــن أحضــرت وبســؤاله عــن املعدلــن لشــاهديه أحضــر‬\n      ‫ال مــن ‪....‬الســعودي بالســجل املدنــي رقــم‪ ....‬و‪ ....‬بالســجل املدنــي‬          ‫ك ً‬\n\n\n‫‪257‬‬\n\f‫ا إننــي‬  ‫رقــم‪ ....‬وبســؤالهما عمــا لديهمــا أفــاد كل واحــد منهمــا قائ ـ ً‬\n‫أعــرف الشــاهدين هذيــن احلاضريــن وهمــا ثقتــان وعــدالن ومــن أهــل‬\n‫الصــاة ولــو شــهدا علــي لقبلــت شــهادتهما هــذا مــا أفــاد بــه كل واحــد‬\n‫منهمــا فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وإلقــرار املدعــى عليــه‬\n‫بــأن مــا حــازة مــن احلبــوب واحلشــيش إمنــا كان لغــرض االســتعمال وأنــه‬\n‫يتعاطــى احلبــوب احملظــورة واحلشــيش املخــدر وألن احلبــوب احملظــورة‬\n‫مــن جنــس احلشــيش املخــدر وإلنــكاره مــا نســبه لــه املدعــي العــام مــن‬\n‫حيازتــه ملــا ذكــر لقصــد االجتــار والترويــج وملــا أحضــره املدعــي العــام‬\n‫مــن البينــة املعدلــة والتــي تضمنــت شــهادتها أن حيــازة املدعــى عليــه ملــا‬\n‫ضبــط معــه إمنــا كان لغــرض الترويــج وألن بينــة املدعــي العام لم تتضمن‬\n‫الشــهادة علــى املدعــى عليــه باســتخدامه لهواتفــه يف مــا نســب لــه وبنــاء‬\n‫علــى الفقــرة األولــى مــن املــادة الثامنــة والثالثــن مــن نظــام مكافحــة‬\n‫املخــدرات وبنــاء علــى الفقــرة الثانيــة مــن املــادة السادســة واخلمســن مــن‬\n‫ذات النظــام ولعــدم وجــود ســوابق جنائيــة علــى املدعــى عليــه ولكونــه‬\n‫مــن خــارج البــاد لــذا وجلميــع مــا تقــدم ثبــت لــدي حيــازة املدعــى عليــه‬\n‫ملــا وصفــه املدعــي العــام يف دعــواه مــن املخــدرات بالقــدر الــذي ذكــره‬\n‫لغــرض الترويــج وقيــام املدعــى عليــه بتعاطــي احلشــيش املخــدر واحلبــوب‬\n‫احملظــورة وقــررت أو ًال جلــد املدعــى عليــه ثمانــن جلــدة حــد املســكر‬\n‫علن ـ ًا يف مــكان عــام ثاني ـ ًا ســجن املدعــى عليــه مــدة أربــع ســنوات‬\n‫يحتســب منهــا مــدة إيقافــه بســبب هــذه القضيــة وجلــده أربعمائــة جلــدة‬\n‫مفرقــة علــى ثمــان دفعــات كل دفعــة عــدد خمســن جلــدة بــن كل‬\n‫دفعــة وأخــرى مــدة أســبوعني وتغرميــه خمســة آالف ريـ‪ 5000‬ــال تــودع‬\n‫يف بيــت مــال املســلمني وتصــرف يف مصــارف املســلمني العامــة ثالث ـ ًا‬\n\n\n                                                                                       ‫‪258‬‬\n\f      ‫صــرف املدعــي العــام عــن طلبــه مبصــادرة مــا ضبــط مــع املدعــى عليــه‬\n      ‫مــن أجهــزة جــوال ومبــا ذكــر حكمــت وأفهمتــه بإبعــاده مــن البــاد‬\n      ‫بعــد تنفيــذ احلكــم عليــه وال يســمح لــه بالعــودة إليهــا إال فيمــا تقضــي بــه‬\n      ‫تعليمــات احلــج والعمــرة وبعــرض احلكــم علــى الطرفــن اعتــرض عليــه‬\n      ‫املدعــي العــام وطلــب اســتئنافه دون تقــدمي الئحــة اعتراضيــة وقنــع بــه‬\n      ‫املدعــى عليــه وســيتم بعــث كامــل املعاملــة حملكمــة االســتئناف لتدقيق‬\n      ‫احلكــم حســب املتبــع وللبيــان حــرر يف ‪1434/1/18‬ه ـ وصلى اهلل وســلم‬\n                                  ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد لقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n      ‫بالدمــام بكتــاب فضيلــة رئيســها رقــم ‪ 34236937‬يف ‪1434/2/13‬ه ـ‬\n      ‫املقيــدة يف هــذه احملكمــة ‪ 34396793‬يف ‪1434/2/17‬ه ـ واحملالــة مــن‬\n      ‫فضيلــة الرئيــس وبرفقهــا إعــام احلكــم الصــادر منــي برقــم ‪3414946‬‬\n      ‫يف ‪1434/1/18‬ه ـ وبرفقهــا قــرار أصحــاب الفضيلــة قضــاة الدائــرة‬\n      ‫اجلزائيــة الثانيــة رقــم ‪ 3431520‬يف ‪1434/2/6‬ه ـ ونصــه بعــد املقدمــة‬\n      ‫وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى‬\n      ‫احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‬\n      ‫حــرر يف ‪1434/2/6‬ه ـ قاضــي اســتئناف‪ ....‬ختمــه وتوقيعــه قاضــي‬\n      ‫اســتئناف‪ ....‬ختمــه وتوقيعــه رئيــس الدائــرة ‪ ....‬ختمــه وتوقيعــه أ‪.‬ه ـ‬\n      ‫وللبيــان حــرر يف ‪1434/2/18‬ه ـ وصلــى اهلل وســلم علــى نبينــا محمــد‬\n                                                         ‫وعلــى آلــه وصحبــه أجمعــن‪.‬‬\n\n\n\n\n‫‪259‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c75d9efa-03f7-50be-835e-660792d35183","source_page_start":253,"source_page_end":259,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d6d0f0747e9b5c816b524531546446c9f0d4bc5fed7b289269db70c22c1c9b3f","normalized_text_hash":"c98aab8e0900110af8407fa7f9bc97a7237f3496862d208b0af0a21f8c89ff26","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v20-p253-3414946"},{"id":"af69e42f-aac6-547e-a95d-af4e039d6e73","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حشيش بقصد التعاطي وتعاطيه وتستر على مصدره -حد املسكر -إقرار -إدانة -التعزير بالسجن واملنع من السفر -عدم التعزير على السوابق.","document_number":"3422856","case_number":"33684837","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/01/26","year":"1434","subject":"مخدرات -حيازة حشيش بقصد التعاطي وتعاطيه وتستر على مصدره -حد املسكر -إقرار -إدانة -التعزير بالسجن واملنع من السفر -عدم التعزير على السوابق.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 3422856:‬تاريخه ‪1434/01/26:‬هـ‬\n                 ‫رقم الدعوى ‪33684837:‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n       ‫‪ 34235696‬تاريخه‪1434/06/10 :‬هـ‬\n\n\n‫مخــدرات‪ -‬حيــازة حشــيش بقصــد التعاطــي وتعاطيــه وتســتر علــى‬\n‫مصــدره‪ -‬حــد املســكر ‪ -‬إقــرار‪ -‬إدانــة ‪ -‬التعزيــر بالســجن واملنــع مــن‬\n                                 ‫الســفر‪ -‬عــدم التعزيــر علــى الســوابق‪.‬‬\n\n\n\n\n‫املواد (‪ )3‬و (‪ )41‬و (‪ )56‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليــه بإدانتــه بحيــازة احلشــيش املخــدر‬\n‫بقصــد التعاطــي وتعاطيــه لــه وتســتره علــى مصــدر مــا ضبــط معــه‪،‬‬\n‫واحلكــم عليــه بإقامــة حــد املســكر لتعاطيــه احلشــيش املخــدر وبعقوبــة‬\n‫الســجن واملنــع مــن الســفر طبقــا لنظــام مكافحــة املخــدرات واملؤثــرات‬\n‫العقليــة مــع تشــديد العقوبــة بحقــه لكثــرة ســوابقه وحيث إنــه مت تفتيش‬\n‫الســيارة التــي يقودهــا فعثــر فيهــا علــى قطعــة مــن احلشــيش املخــدر‪،‬‬\n‫وأثبت التقرير الكيميائي الشــرعي إيجابية القطعة املرســلة للحشــيش‬\n‫املخــدر ‪ ،‬كمــا أقــر أمــام احملكمــة مبــا أســنده إليــه املدعــي العــام مــن‬\n‫احليــازة والتعاطــي وأنكــر التســتر‪ ،‬وقضــت احملكمــة بإدانــة املدعــى‬\n‫عليــه بتعاطــي احلشــيش املخــدر وحيازتــه بقصــد التعاطــي وقــررت جلــده‬\n‫حــد شــرب املســكر ثمانــن جلــدة وســجنه ملــدة ثمانيــة أشــهر ومنعــه‬\n\n                                                                                     ‫‪260‬‬\n\f      ‫مــن الســفر خــارج اململكــة ملــدة ســنتني‪ ،‬وقنــع املدعــى عليــه باحلكــم‬\n      ‫وعــارض املدعــي العــام عليــه‪ ،‬وقــررت محكمــة االســتئناف املصادقــة‬\n                                                                     ‫علــى احلكــم‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا‪ ....‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بالريــاض برقــم ‪ 33684837‬وتاريــخ ‪ 1433/11/30‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 332157749‬وتاريــخ ‪ 1433/11/30‬ه ـ ففــي يــوم‬\n      ‫األحــد املوافــق‪ 1434/01/25‬ه ـ افتتحــت اجللســة الســاعة ‪11 :45‬‬\n      ‫وادعــى املدعــي العــام ‪........‬علــى ‪ ،......... /‬البالــغ مــن العمــر (‪)21‬‬\n      ‫عامــا‪ ،‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪)....................‬‬  ‫ً‬\n      ‫أعــزب ‪ ،‬متعلــم ‪ ،‬متســبب ‪ ،‬يقيــم مبدينــة الريــاض ‪ ،‬أوقــف بتاريــخ‬\n      ‫‪1433/10/21‬ه ـ وأحيــل إلــى شــعبة ســجن امللــز مبوجــب أمــر اإلحالــة‬\n      ‫ومتديــد التوقيــف رقــم (‪ )........‬وتاريــخ ‪1433/10/24‬ه ـ اســتناد ًا لبرقيــة‬\n      ‫ســمو ولــي العهــد وزيــر الداخلية رقم (‪ )79452‬وتاريــخ‪ 1432/12/20‬هـ‬\n      ‫لوجــود ســابقتي مخــدرات مســجلة عليــه عــام ‪1431‬ه ـ بقولــه انــه بتاريــخ‬\n      ‫‪1433/10/21‬ه ـ قبــض علــى املذكــور مــن قبــل إحــدى فــرق دوريــات‬\n      ‫األمــن أثنــاء قيــام الفرقــة بعملهــا حيــث شــاهدت ســيارة مــن نــوع (‪)......‬‬\n      ‫حتمــل اللوحــة رقــم (‪ ).........‬بقيــادة املذكــور ولالشــتباه بــه مت اســتيقافه‬\n      ‫وبتفتيــش الســيارة وجــد فــوق طبلــون الســيارة قطعــة يشــتبه أن تكــون‬\n      ‫مــن احلشــيش املخــدر بلــغ وزنهــا (‪ )0,1‬عشــر اجلــرام واعتــرف املذكــور‬\n      ‫لــدى الفرقــة القابضــة بأنهــا تعــود لــه بقصــد االســتعمال الشــخصي‪.‬‬\n\n‫‪261‬‬\n\f‫وقــد أثبــت التقريــر الكيميائــي الشــرعي الصــادر مــن مركــز مراقبــة‬\n‫الســموم والكيميــاء الطبيــة الشــرعية املرفــق رقــم (‪ )........‬لعــام ‪1433‬هـ‬\n‫ايجابيــة القطعــة املضبوطــة للحشــيش وهــو مــن املــواد املخــدرة املدرجــة‬\n‫باجلــدول رقــم (‪ )1‬فئــة (‪ )1‬امللحــق بنظــام مكافحــة املخــدرات واملؤثرات‬\n‫العقلية‪ .‬وبســماع اقواله االولية اعترف بحيازته لقطعة احلشــيش املخدر‬\n‫املضبوطــة بقصــد التعاطــي ‪ ،‬وبتعاطيــه احلشــيش املخــدر وأن آخــر مــرة‬\n‫تعاطــى فيهــا قبــل أســبوع ‪ ،‬ولــم يــدلِ مبعلومــات عــن مصــدر مــا ضبــط‬\n‫وقــد أســفرت إجــراءات التحقيــق عــن توجيــه االتهــام لــ‪ /‬بحيــازة قطعــة‬\n‫مــن احلشــيش املخــدر بلــغ وزنهــا (‪ )0,1‬عشــر اجلــرام بقصــد التعاطــي‬\n‫وتعاطيــه احلشــيش املخــدر املجــرم مبوجــب املــادة (الثالثــة) مــن نظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم‬\n‫(م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ وتســتره علــى مصــدر مــا ضبــط املعاقــب‬\n‫علــى ذلــك شــرعاً‪ .‬وذلــك لألدلــة والقرائــن التاليــة‪-1 -:‬مــا تضمنــه‬\n‫اعترافــه مبحضــر ســماع أقوالــه األوليــة املنــوه عنــه املــدون علــى اللفــة‬\n‫رقــم (‪-2 .)8‬مــا تضمنــه محضــر القبــض املنــوه عنــه املــدون علــى اللفــة‬\n‫رقــم (‪-3 .)1‬مــا تضمنــه التقريــر الكيميائــي الشــرعي املرفــق لفــه رقــم‬\n‫(‪ .) 13‬وببحــث ســوابقه تبــن ان عليــه أربــع ســوابق األولــى والثانية حيازة‬\n‫واســتعمال مخــدرات والثالثــة اقامــة عالقــة غيــر شــرعية والرابعــة شــرب‬\n‫املسكرات‪ .‬وحيث إن ما أق ــدم عل ــيه ال ــمذكور ف ــعل م ــحرم وم ــعاقب‬\n‫عليــه شــرع ًا ونظام ـ ًا لــذا أطلــب إثبــات إدانتــه مبــا أســند إليــه واحلكــم‬\n‫عليــه باآلتــي‪-1 :‬بعقوبــة تعزيريــة بحقــه اســتنادا للفقــرة األولــى مــن‬\n‫املــادة (‪ ) 41‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة لقــاء مــا‬\n‫أســند إليــه ‪-2‬بحــد املســكر لقــاء تعاطيــه احلشــيش املخــدر‪-3 .‬تشــديد‬\n\n\n                                                                                        ‫‪262‬‬\n\f      ‫العقوبــة بحقــه لكثــرة ســوابقه اســتناد ًا لبرقيــة صاحــب الســمو امللكــي‬\n      ‫نائــب وزيــر الداخليــة رقــم (‪ )93958/5/5/1‬وتاريــخ ‪1429/8/23‬هــ‪-4‬‬\n      ‫منعــه مــن الســفر إلــى خــارج اململكــة بعــد انتهــاء تنفيــذ عقوبــة الســجن‬\n      ‫وف ــق ًا للفقــرة ( األولــى ) مــن املــادة (‪ )56‬مــن النظــام املشــار إليــه‪.‬‬\n      ‫‪-5‬بعقوبــة تعزيريــة بحقــه لقــاء تســتره علــى مصــدر مــا ضبــط هــذه‬\n      ‫ا إن مــا ذكــره املدعــي العــام‬‫دعــواي وبعــرض الدعــوى عليــه أجــاب قائـ ً‬\n      ‫يف دعــواه كلــه صحيــح جملــة وتفصيــا فقــد وجــد بحيازتــي قطعــة‬\n      ‫مــن احلشــيش املخــدر بلــغ وزنهــا (‪ )0,1‬عشــر اجلــرام بقصــد التعاطــي‬\n      ‫فقــط وقــد كنــت أتعاطــى احلشــيش قبــل أن يقبــض علــي بأســبوع وامــا‬\n      ‫املصــدر الــذي كان يزودنــي فهــو رقــم جوالــه وهــو ســاكن يف احلــي‬\n      ‫الــذي أســكن فيــه املخطــط ‪........‬قريــب جــدا مــن شــارع ‪........‬هكــذا‬\n      ‫أجــاب وقــد جــرى الرجــوع إلــى املعاملــة فوجــدت بــن طياتهــا محضــر‬\n      ‫القبــض والتقريــر الكيميائــي الشــرعي وبطاقــة الســوابق فوجدتهــا‬\n      ‫كمــا ذكــر املدعــي العــام فبنــاء علــى مــا ســلف مــن الدعــوى واإلجابــة‬\n      ‫املتضمنــة إقــراره مبــا نســب إليــه وملــا جــاء يف محضــر القبــض والتقريــر‬\n      ‫الكيميائــي الشــرعي وحيــث قــام املدعــى عليــه بالكشــف عــن املصــدر‬\n      ‫وملــا جــاء يف املــواد(‪ )56 -41‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n      ‫العقليــة املشــار إليهــا أعــاه وملــا قــرره مــن نــدم وتوبــة عليــه فقــد ثبــت‬\n      ‫لــدي إدانــة املدعــى عليــه بحيــازة قطعــة مــن احلشــيش املخــدر بلــغ وزنهــا‬\n      ‫(‪ )0,1‬عشــر اجلــرام بقصــد التعاطــي وتعاطيــه احلشــيش املخــدر املجــرم‬\n      ‫مبوجــب املــادة (الثالثــة) مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n      ‫العقليــة الصــادر باملرســوم امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ‬\n      ‫وحكمــت بســجنه ملــدة ثمانيــة أشــهر اعتبــارا مــن تاريــخ إيقافــه وجلــدة‬\n\n\n‫‪263‬‬\n\f‫مائــة وعشــرين جلــده مفرقــة علــى ثــاث دفعــات بني كل دفعــة واألخرى‬\n‫مــدة ال تقــل عــن أســبوعني وكل دفعــة أربعــن جلــده لقــاء تعــدد ســوابقه‬\n‫وجلــده حــد شــرب املســكر وهــي ثمانــن جلــدة ومنعــه مــن الســفر‬\n‫للخــارج ملــدة ســنتني بعــد انتهــاء محكوميتــه وبعــرض احلكــم عليــه قنــع‬\n‫بــه و قــرر املدعــي العــام االعتــراض وطلــب متييــز احلكــم بــدون الئحــة‬\n‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                             ‫وســلم‪ .‬حــرر يف ‪1434/01/25‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء املوافق‪1434/05/07‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 11:30‬وقــد عــادت املعاملــة مــن محكمــة‬\n‫االســتئناف بالريــاض وبرفقهــا قــرار الدائــرة اجلزائيــة الثالثــة رقــم‬\n‫‪ 34190096‬يف ‪1434/4/16‬ه ـ املتضمــن انــه بدراســة القــرار وصــورة‬\n‫ضبطــه وأوراق املعاملــة قررنــا باألكثريــة إعادتهــا ملالحظــة مــا يلــي‪/‬‬\n‫حكــم فضيلتــه علــى املدعــى عليــه بجلــده مائــة وعشــرين جلــده لقــاء‬\n‫تعــدد ســوابقه وهــذا يف غيــر محلــه فســوابقه التــي عليــه قــد حكــم‬\n‫عليــه فيهــا وأخــذ جــزاءه عليهــا فــا يعــاد عليــه احلكــم فيهــا مــرة أخــرى‬\n‫فعلــى فضيلتــه إعــادة النظــر يف ذلــك ثانيــا‪ /‬يوجــد نقــص يف صــورة‬\n‫ضبــط القــرار وهــو أول الدعــوى يتعــن إرفــاق هــذا النقــص أ‪.‬ه ـ عليــه‬\n‫أجيــب أصحــاب الفضيلــة أنــي ولوجاهــة مــا ذكــروا فقــد رجعــت عمــا‬\n‫حكمــت بــه بخصــوص اجللــد ومت اتخــاذ الــازم حيــال املالحظــة الثانيــة‬\n‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                         ‫وســلم‪ .‬حــرر يف ‪ 1434/05/07‬ه ـ ‪.‬‬\n‫احلمــدهلل وحــده وبعــد ففــي يــوم الثالثــاء ‪ 1434/6/ 27‬ه ـ فتحت اجللســة‬\n‫الســاعة الواحــدة إال ربــع وقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n\n\n                                                                                      ‫‪264‬‬\n\f      ‫بالريــاض وبرفقهــا قــرار الدائــرة اجلزائيــة الثانيــة رقــم ‪34235696‬‬\n      ‫وتاريــخ ‪ 1434/6/10‬ه ـ املتضمــن املصادقــة علــى احلكــم وصلــى اهلل‬\n                                                    ‫وســلم علــى نبينــا محمــد ‪.‬‬\n\n\n\n\n‫‪265‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c75d9efa-03f7-50be-835e-660792d35183","source_page_start":260,"source_page_end":265,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"531bb05c538e942ea58053d48b710578a449d465ee7db295eb1a6752ab3cab80","normalized_text_hash":"a6270fec026ed94e8319d8b4c03f5952cd23db93d4aa5c2e933f1281a4fa7e12","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v20-p260-3422856"},{"id":"5db20c63-12b4-558b-a4b9-c2759783f5b6","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حشيش وحبوب محظورة بقصد التعاطي -تستر على مصدرها -حيازة مسكر بقصد االستعمال -هروب من رجال األمن -إقرار -إدانة -التعزير باجللد والسجن واملنع من السفر.","document_number":"345917","case_number":"33685113","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف باألكثرية املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/01/07","year":"1434","subject":"مخدرات -حيازة حشيش وحبوب محظورة بقصد التعاطي -تستر على مصدرها -حيازة مسكر بقصد االستعمال -هروب من رجال األمن -إقرار -إدانة -التعزير باجللد والسجن واملنع من السفر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك‪ 345917:‬تاريخه ‪1434/01/07:‬هـ‬\n                   ‫رقم الدعوى ‪33685113:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 3430812‬تاريخه‪ 1434/02/05:‬هـ‬\n\n\n‫مخــدرات‪ -‬حيــازة حشــيش وحبــوب محظــورة بقصــد التعاطــي ‪ -‬تســتر‬\n‫علــى مصدرهــا‪ -‬حيــازة مســكر بقصــد االســتعمال‪ -‬هــروب مــن رجــال‬\n ‫األمــن‪ -‬إقــرار‪ -‬إدانــة ‪ -‬التعزيــر باجللــد والســجن واملنــع مــن الســفر‪.‬‬\n\n\n\n\n      ‫املواد (‪ )41‬و (‪ )56‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليــه بحيــازة حشــيش مخــدر‬\n‫وحبــوب البــرازوالم احملظــورة بقصــد التعاطــي وحيــازة مســكر‬\n‫بقصــد االســتعمال وتســتره علــى مصــدر وهروبــه مــن الفرقــة القابضــة‪،‬‬\n‫واحلكــم عليــه بعقوبــة الســجن واملنــع مــن الســفر طبقــا لنظــام مكافحة‬\n‫املخــدرات واملؤثــرات العقليــة وعقوبــة تعزيريــة علــى باقــي التهــم‪ ،‬حيــث‬\n‫إنــه مت تفتيــش ســيارة املدعــى عليــه بعــد ارتطامهــا بجــدار أحــد املنــازل‬\n‫أثنــاء هروبــه مــن رجــال األمــن فعثــر فيهــا علــى حشــيش مخــدر وحبــوب‬\n‫االلبــرازوالم احملظــورة وقــارورة مســكر و أثبــت التقريــر الكيميائــي‬\n‫الشــرعي إيجابيــة املضبوطــات للحشــيش املخــدر ولعقــار البــرازوالم‬\n‫وللكحــول‪ ،‬كمــا أقــر املدعــى عليــه أمــام احملكمــة مبــا أســنده إليــه‬\n‫املدعــي العــام ‪ ،‬فقضــت احملكمــة بإدانــة املدعــى عليــه بجميــع ما نســب‬\n\n                                                                                    ‫‪266‬‬\n\f      ‫إليــه وقــررت ســجنه ملــدة ثمانيــة أشــهر ومنعــه مــن الســفر خــارج اململكــة‬\n      ‫مــدة ســنتني وجلــده مائــة جلــدة مفرقــة علــى فترتــن لقــاء بقيــة التهــم‬\n      ‫املنســوبة لــه‪ ،‬وقنــع املدعــى عليــه باحلكــم وعــارض املدعــي العــام عليــه‪،‬‬\n           ‫وقــررت محكمــة االســتئناف باألكثريــة املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا‪ ....‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بالريــاض برقــم ‪ 33685113‬وتاريــخ ‪ 1433/11/30‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 332159206‬وتاريــخ ‪ 1433/11/30‬ه ـ ففــي يــوم‬\n      ‫األربعــاء املوافق‪1434/01/07‬ه ـ افتتحــت اجللســة الســاعة ‪01 :00‬‬\n      ‫وفيهــا حضــر املدعــي العــام وادعــى علــى ‪ ....‬البالــغ مــن العمــر( ‪) 29‬‬\n      ‫عام ـاً‪ .... ،‬ســعودي اجلنســية مبوجــب بطاقــة الهويــة الوطنيــة رقــم (‪)....‬‬\n      ‫أعــزب‪ ،‬متعلــم‪ ،‬متســبب‪ ،‬يقيــم يف مدينــة الريــاض‪ ،‬أوقــف بتاريــخ‬\n      ‫‪1433/10/19‬ه ـ وأحيــل إلــى شــعبة ســجن امللــز مبوجــب أمــر إحالــة‬\n      ‫ومتديــد توقيــف رقــم (‪ )........‬وتاريــخ ‪1433/10/23‬ه ـ اســتناد ًا لبرقيــة‬\n      ‫ســمو ولــي العهــد نائــب رئيــس مجلــس الــوزراء وزيــر الداخليــة رقــم‬\n      ‫(‪ )79425‬وتاريــخ ‪1432/12/20‬ه ـ لوجــود ســابقه مخــدرات مســجلة‬\n      ‫بحقــه عــام ‪1432‬هــ‪ .‬حيــث إنــه بتاريــخ ‪1433/10/19‬هــ‪ ،‬قبــض علــى‬\n      ‫املذكــور مــن قبــل إحــدى فــرق دوريــات األمــن مبنطقــة الريــاض أثنــاء‬\n      ‫قيــام الفرقــة بعملهــا حيــث شــاهدت ســيارة مــن نــوع (‪ )...‬حتمــل اللوحــة‬\n      ‫رقــم (‪ )....‬وعنــد طلــب إثباتــه ارتكــب الفــرار داخــل احلــي ممــا أدى إلــى‬\n      ‫ارتطامه بجدار منزل ورصيف‪ ،‬وبتفتيش الســيارة عثر على ســيجارتني‬\n\n‫‪267‬‬\n\f‫ملفوفتــن تزنــان جميع ـ ًا (‪ )1.8‬جرام ـ ًا واحــد ًا وثمانيــة أعشــار اجلــرام‪،‬‬\n‫يشــتبه أن يكــون تبغهمــا مخلوطـ ًا باحلشــيش املخــدر‪ ،‬وعــدد (‪ )2‬حبتــن‬\n‫مــن نــوع (زنكــس)‪ ،‬كمــا عثــر علــى قــارورة مــاء ســعة (‪ )0.33‬لتــر‬\n‫بهــا النصــف مــن ســائل يحتمــل أن يكــون مــن العــرق املســكر‪ .‬وقــد‬\n‫أثبــت التقريــر الكيميائــي الشــرعي الصــادر مــن مركــز مراقبــة‬\n‫الســموم والكيميــاء الطبيــة الشــرعية بالريــاض املرفــق رقــم (‪)........‬‬\n‫لعــام ‪1433‬ه ـ ايجابيــة مســتخلص تبــغ الســيجارتني للحشــيش وهــو‬\n‫مــن املــواد املخــدرة املدرجــة باجلــدول رقــم (‪ )1‬فئــة ( أ ) امللحــق بنظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة‪ ،‬وايجابيــة احلبتــن املضبوطتــن‬\n‫لعقــار اإللبــرازوالم وهــو مــن املــواد املدرجــة باجلــدول رقــم (‪ )2‬فئــة ( د )‬\n‫امللحــق بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة وإيجابيــة عينــة‬\n‫الســائل املضبــوط يف القــارورة ملــادة الكحــول بنســبة (‪ .)%37‬وبســماع‬\n‫أقوالــه األوليــة اقــر بحيــازة مــا ضبــط معــه بقصــد التعاطــي‪ ،‬ولــم يــدل‬\n‫مبعلومــات عــن مصــدر مــا ضبــط‪ .‬وقــد أســفرت إجــراءات التحقيــق‬\n‫عــن توجيــه االتهــام ل ـ ــ‪ /‬بحيــازة ســيجارتني مخلــوط تبغهمــا باحلشــيش‬\n‫املخــدر تزنــان جميع ـ ًا (‪ )1.8‬جرام ـ ًا واحــد وثمانيــة أعشــار اجلــرام‬\n‫و(‪ )2‬حبتــن حتمــان عالمــة (الزنكــس) احملظــورة االيجابيــة لعقــار‬\n‫اإللبــرازوالم بقصــد التعاطــي املجــرم مبوجــب املــادة (الثالثــة) مــن نظــام‬\n‫مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي‬\n‫رقــم(م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ وحيــازة مســكر بقصــد الشــرب‬\n‫وتســتره علــى مصــدر وهروبــه مــن الفرقــة القابضــة املعاقــب علــى ذلــك‬\n‫شــرعاً‪ .‬وذلــك لألدلــة والقرائــن التاليــة‪ .1 :‬مــا تضمنــه اعترافــه مبحضــر‬\n‫ســماع أقوالــه األوليــة املنــوه عنــه املــدون علــى اللفتــن رقــم (‪ )....‬ورقــم‬\n\n\n                                                                                       ‫‪268‬‬\n\f      ‫(‪ .2 )....‬مــا تضمنــه محضــر القبــض املنــوه عنــه املرفــق لفــه رقــم (‪)1‬‬\n      ‫‪.3‬مــا تضمنــه التقريــر الكيميائــي الشــرعي املنــوه عنــه املرفــق لفــة‬\n      ‫رقــم (‪ )....‬وببحــث ســوابقه اتضــح وجــود ثــاث ســوابق مســجله عليــه‬\n      ‫األولــى حيــازة واســتعمال مخــدرات والثانيــة حيــازة مخــدرات والثالثــة‬\n      ‫حيــازة واســتعمال مخــدرات وتســتر علــى مــروج‪ .‬وحيــث إن مــا أقــدم عليه‬\n      ‫املذكــور فعــل محــرم ومعاقــب عليــه شــرع ًا ونظام ـ ًا لــذا اطلــب إثبــات‬\n      ‫إدانتــه مبــا أســند إليــه واحلكــم باآلتــي‪ )1 :‬بالعقوبــة الــواردة يف الفقــرة‬\n      ‫(األولــى) مــن املــادة (‪ )41‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n      ‫العقليــة املشــار إليــه لقــاء مــا اســند إليــه‪ )2 .‬منعــه مــن الســفر إلــى خــارج‬\n      ‫اململكــة بعــد انتهــاء تنفيــذ عقوبــة ســجنه وفق ـ ًا للفقــرة (األولــى) مــن‬\n      ‫املــادة (‪ )56‬مــن النظــام املشــار إليــه‪ )3 .‬بعقوبــة تعزيريــة لقــاء حيازتــه‬\n      ‫املســكر بقصــد شــربه وتســتره علــى مصــدر مــا ضبــط وهروبــه مــن‬\n      ‫الفرقــة القابضــة تشــديد العقوبــة عليــه لقــاء كثــرة ســوابقه اســتناد ًا‬\n      ‫إلــى برقيــه ســمو نائــب وزيــر الداخليــة رقــم (‪ )93958/5/5/1‬وتاريــخ‬\n      ‫‪1429/8/23‬هــ‪ .‬وبــاهلل التوفيــق هــذا وباســتجواب املدعــى عليــه فقــال‬\n      ‫مــا ذكــره املدعــي العــام يف دعــواه كلــه صحيــح فقــد مت القبــض علــي‬\n      ‫وعثــر يف ســيارتي علــى ســيجارتني مخلــوط تبغهمــا باحلشــيش تزنــان‬\n      ‫(‪1,8‬جــم) وعلــى حبتــن زنكــس وعلــى قــارورة صغيره بهــا النصف عرق‬\n      ‫مســكر تعــود لــي جميعــا بقصــد التعاطــي وحصلــت عليهــا بالشــراء مــن‬\n      ‫شــخص ال أعرفــه بحــي ‪........‬والســوابق الثــاث املســجلة علــي صحيحــة‬\n      ‫وأنــا هربــت مــن الفرقــة ألننــي كنــت خائفــا هــذا كمــا جــرى االطــاع‬\n      ‫علــى املعاملــة ووجــدت التقريــر الكيميائــي الشــرعي رقــم ‪/9743‬س‬\n      ‫واملتضمــن ثبــوت ايجابيــة مســتخلص تبــغ الســيجارتني للحشــيش وثبــوت‬\n\n\n‫‪269‬‬\n\f‫ايجابيــة ســائل القــارورة للكحــول بنســبه ‪ %37‬وثبــوت ايجابيــة كل‬\n‫حبــه لعقــار االلبرازوالم‪.‬أهــ‪ .‬فنظــرا ملــا تقــدم مــن الدعــوى واإلجابــة‬\n‫وحيــث صــادق املدعــى عليــه علــى مــا جــاء يف دعــوى املدعــي العــام‬\n‫فقــد ثبــت لــدي إدانتــه بحيــازة ســيجارتني مخلــوط تبغهمــا باحلشــيش‬\n‫تزنــان (‪1,8‬جــم) و حبتــن زنكــس و قــارورة صغيــره بهــا النصــف عــرق‬\n‫مســكر بقصــد التعاطــي وحكمــت عليــه تعزيــرا بســجنه ملــده ثمانيــة‬\n‫اشــهر اعتبــارا مــن تاريــخ توقيفــه ومبنعــه مــن الســفر خلــارج اململكــة‬\n‫ملــده ســنتني بعــد تنفيــذ عقوبــة ســجنه متشــيا مــع املادتــن ( ‪ )56-41‬مــن‬\n‫نظــام مكافحــة املخــدرات كمــا حكمــت عليــه تعزيــرا لقــاء بقيــة مــا‬\n‫نســب اليــه بجلــده مائــة جلــدة مفرقــة علــى فترتــن بينهمــا أســبوع هــذا‬\n‫وبعــرض ذلــك علــى املدعــى عليــه قــرر القناعــة باحلكــم أمــا املدعــي‬\n‫العــام فقــرر عــدم القناعــة معتبــرا الئحــة الدعــوى الئحــة اعتراضيــة علــى‬\n‫احلكــم وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر‬\n                                                        ‫يف ‪1434/01/07‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة األولــى‬\n‫اجلزائيــة مبحكمــة االســتئناف بالريــاض علــى املعاملــة الــواردة مــن‬\n‫فضيلــة رئيــس احملكمــة اجلزائيــة بالريــاض برقــم ‪33/2159206‬‬\n‫وتاريــخ ‪1434/01/13‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة‬\n‫القاضــي باحملكمــة الشــيخ ‪ ....... /‬املســجل برقــم ‪ 345917‬وتاريــخ‬\n‫‪ 1434/01/07‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد ‪ ....../‬بشــأن‬\n‫قضيــة مخــدرات علــى النحــو املوضــح بالقــرار املتضمــن حكــم‬\n‫فضيلتــه مبــا هــو مــدون ومفصــل بــه وبدراســة القــرار وصــورة ضبطــة‬\n‫وأوراق املعاملــة لــم يظهــر باالكثريــة مــا يوجــب املالحظــة وبــاهلل‬\n                                                                     ‫التوفيــق ‪.‬‬\n                                                                                    ‫‪270‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c75d9efa-03f7-50be-835e-660792d35183","source_page_start":266,"source_page_end":270,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"1e15aa92231b96695daa56029ba0aaae58c6d82490313c09432cb903beaac245","normalized_text_hash":"782ed3d147f28e76a81dd35448ed5f401f34a692d17708bf7049170345d5b347","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v20-p266-345917"},{"id":"664ba792-7027-5e72-87f0-5a5d75e67375","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حشيش وحبوب محظورة بقصد التعاطي والترويج -بينة غير موصلة -إدانة باحليازة املجردة عن القصد - اكتفاء بالعقوبة األشد -تعزير بالسجن واجللد والغرامة -منع من السفر -إتاف املخدرات .","document_number":"34283200","case_number":"33685705","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املوافقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/07/30","year":"1434","subject":"مخدرات -حيازة حشيش وحبوب محظورة بقصد التعاطي والترويج -بينة غير موصلة -إدانة باحليازة املجردة عن القصد - اكتفاء بالعقوبة األشد -تعزير بالسجن واجللد والغرامة -منع من السفر -إتاف املخدرات .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34283200 :‬تاريخه ‪1434/07/30:‬هـ‬\n                         ‫رقم الدعوى ‪33685705:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34325787‬تاريخه‪1434/10/06:‬ه‬\n\n\n       ‫مخــدرات ‪ -‬حيــازة حشــيش وحبــوب محظــورة بقصــد التعاطــي‬\n       ‫والترويــج ‪ -‬بينــة غيــر موصلــة ‪ -‬إدانــة باحليــازة املجــردة عــن القصــد ‪-‬‬\n       ‫اكتفــاء بالعقوبــة األشــد ‪ -‬تعزيــر بالســجن واجللــد والغرامــة ‪ -‬منــع‬\n                                                  ‫مــن الســفر ‪ -‬إتــاف املخــدرات ‪.‬‬\n\n\n\n              ‫املواد (‪ )39‬و(‪ )56‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n\n\n\n\n       ‫دعــوى جزائيــة عامــة ضــد املدعــى عليــه تتضمــن طلــب إثبــات إدانتــه‬\n       ‫بحيــازة احلشــيش املخــدر بقصــد الترويــج وحيــازة نصــف حبــة مــن‬\n       ‫حبــوب اإلمفيتامــن بقصــد التعاطــي‪ ،‬واحلكــم عليــه بعقوبــة الســجن‬\n       ‫واجللــد والغرامــة واملنــع مــن الســفر طبقــا لنظــام مكافحــة املخــدرات‬\n       ‫واملؤثــرات العقليــة‪ ،‬مت االتفــاق معــه علــى شــراء احلشــيش املخــدر فوافــق‬\n       ‫علــى ذلــك وحضــر يف الوقــت واملــكان احملدديــن وعنــد مشــاهدته‬\n       ‫رجــل األمــن حــاول الهــرب ورمــى شــيئا كان يف يــده فتــم القبــض عليــه‬\n       ‫وبتفتيشــه عثــر معــه علــى نصــف حبــة محظــورة وبالتأكــد مــن الشــيء‬\n       ‫الــذي قــام برميــه تبــن أنهمــا قطعتــان يشــتبه أن تكــون مــن احلشــيش‪،‬‬\n       ‫أثبــت التقريــر الكيميائــي الشــرعي إيجابيــة العينــة املرســلة للحشــيش‬\n\n‫‪271‬‬\n\f‫املخــدر‪ ،‬أقــر أمــام احملكمــة مبــا أســنده إليــه املدعــي العــام مــن حيازتــه‬\n‫للحبــوب احملظــورة بقصــد التعاطــي وأنكــر حيــازة احلشــيش املخــدر‬\n‫بقصــد الترويــج‪ ،‬طلبــت احملكمــة مــن املدعــي العــام تقــدمي بيناتــه‬\n‫وقــررت ســماع شــهادة شــهود محضــر القبــض فلــم جتــد فيهــا مــا يثبــت‬\n‫قصــد الترويــج مــن احليــازة‪ ،‬قضــت احملكمــة بإدانــة املدعــى عليــه‬\n‫بحيــازة احلبــوب احملظــورة بقصــد التعاطــي وإدانتــه بحيــازة احلشــيش‬\n‫املخــدر حيــازة مجــردة وقــررت االكتفــاء بالعقوبــة األشــد وذلــك بســجنه‬\n‫ملــدة ســنتني وجلــده أربعــن جلــدة تكــرر عليــه خمس مــرات وتغرميه مبلغ‬\n‫ثالثــة آالف ريــال ومنعــه مــن الســفر خــارج اململكــة ملــدة ســنتني وإتــاف‬\n‫املخــدرات احملــرزة‪ ،‬قنــع املدعــى عليــه باحلكــم وعــارض املدعــي العــام‬\n               ‫عليــه‪ ،‬قــررت محكمــة االســتئناف املوافقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمد هلل وحده وبعد فلدي أنا‪ ....‬القاضي يف احملكمة اجلزائية باملدينة‬\n‫املنــورة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة باملدينــة املنــورة برقــم ‪ 33685705‬وتاريــخ ‪1433/12/01‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 332163323‬وتاريــخ ‪ 1433/12/01‬ه ـ‬\n‫ففــي يــوم األحــد املوافــق ‪1434/01/18‬ه ـ افتتحــت اجللســة الســاعة‬\n‫‪ 09 :45‬وفيهــا ادعــى املدعــي العــام ‪....‬ســعودي مبوجــب الســجل املدنــي‬\n‫رقــم‪ ....‬والتعميــد رقــم ‪ 17648‬يف ‪1432/6/12‬ه ـ علــى ‪....‬ســعودي‬\n‫مبوجــب الســجل املدنــي رقــم‪ ....‬أوقــف بتاريــخ ‪1433/10/15‬ه ـ وأحيــل‬\n‫للســجن العــام قائــا يف حتريــر دعــواه أنــه باالطــاع علــى محضــر فرقــة‬\n‫مكافحــة املخــدرات بتاريــخ ‪1433/10/15‬ه ـ وبنــاء علــى اإلخباريــة‬\n\n                                                                                       ‫‪272‬‬\n\f      ‫املدونــة عــن قيــام املذكــور أعــاه والــذي يعمــل بشــركة بترويــج مــادة‬\n      ‫احلشــيش املخــدر عليــه مت متكــن املصــدر مــن االتصــال علــى اجلــوال‬\n      ‫اخلــاص باملــروج رقــم (‪ ).........‬وطلــب منــه (حشــيش) مببلــغ خمســمائة‬\n      ‫ريــال فقــال املــروج (أوصــل الطلبيــة وأمــر البيــت أجيبهــا لــك فــرد املصــدر‬\n      ‫أنــا أنتظــرك بغرفتــي ) وكان ذلــك حتــت مســمع بعــض أفــراد الفرقــة‬\n      ‫القابضــة عليــه مت إعــداد الكمــن املوافــق للطــرق النظاميــة وبعــد‬\n      ‫نصــف ســاعة خــرج املــروج علــى الســيارة العائــدة للمطعــم وتوقــف أمــام‬\n      ‫ســكن املصــدر وصعــد للملحــق الــذي يقيــم بــه املصــدر وعنــد مشــاهدته‬\n      ‫ألحــد أفــراد الفرقــة حــاول اإلفــات خوفــا مــن انكشــاف أمــره لكونــه‬\n      ‫مــن أربــاب الســوابق ورمــى شــيئا كان بيــده أمــام أنظــار الفرقــة فتــم‬\n      ‫القبــض عليــه وبتفتيشــه عثــر بجيــب بنطلونــه علــى نصــف حبــه يشــتبه أن‬\n      ‫تكــون مــن احلبــوب احملظــورة وبالتأكــد مــن الشــيء الــذي قــام برميــه‬\n      ‫أتضــح بأنهــا قطعتــان ســوداء اللــون وزنهــا أربعــة عشــر جرامــا وثالثــة‬\n      ‫مــن عشــرة مــن اجلــرام يشــتبه أنهــا مــن احلشــيش املخــدر فتــم حتريــز‬\n      ‫كافــة املضبوطــات وباســتجوابه أقــر باحلضــور ملقــر ســكن املصــدر ملــا‬\n      ‫تربطهمــا مــن عالقــة عمــل قائمــة بينهمــا ( حيــث أن املصــدر هــو املديــر‬\n      ‫املباشــر للمذكــور ) كمــا أقــر بحيــازة نصــف حبــه محظــورة بقصــد‬\n      ‫التعاطــي إال أنــه أنكــر حيازتــه للحشــيش املخــدر أو قيامــه بالترويــج‬\n      ‫وقــد أثبــت التقريــر الكيميائــي الشــرعي رقــم ‪ 2129‬ك م إيجابيــة‬\n      ‫عينــة القطــع املرســلة للحشــيش املخــدر وانتهــى التحقيــق وإلــى توجيــه‬\n      ‫االتهــام إليــه بحيــازة قطعتــن ســوداوي اللــون وزنهمــا أربعــة عشــر جرامــا‬\n      ‫وثالثــة مــن عشــرة مــن اجلــرام (‪ )14,3‬بقصــد الترويــج وحيــازة نصــف‬\n      ‫حبــه مــن احلبــوب احملظــورة بقصــد التعاطــي وذلــك لألدلــة التاليــة ‪-1‬‬\n\n\n‫‪273‬‬\n\f‫مــا جــاء مبحضــر القبــض ‪ -2‬مــا ورد بالتقريــر الكيميائــي الشــرعي‬\n‫رقــم ‪2232‬ك م ‪ -3‬مــا ورد بإقــراره باحليــازة للتعاطــي وأقوالــه املدونــة‬\n‫وحيــث أن مــا أقــدم عليــه املذكــور فعــل محــرم ومعاقــب عليــه شــرعا‬\n‫ومعاقــب عليــه نظامــا مبوجــب نظــام مكافحــة املخــدرات واملؤثــرات‬\n‫العقليــة املــادة الثالثــة الفقــرة الثانيــة أطلــب إثبــات مــا أســند إليــه‬\n‫واحلكــم عليــه باالتــي ‪ -1‬عقوبــة الســجن واجللــد والغرامــة األصليــة‬\n‫اســتنادا للمــادة ‪ -2 1/38‬عقوبــة املنــع مــن الســفر التكميليــة خــارج‬\n‫اململكــة اســتنادا للمــادة ‪ -3 1/56‬تشــديد العقوبــة عليــه لقــاء ســوابقه‬\n‫املتكــررة والتــي لــم تردعــه عقوباتهــا الســابقة اســتنادا لتعميــم وزيــر‬\n‫الداخليــة رقــم ‪ 93958‬وتاريــخ ‪1429/8/13‬ه ـ ثــم أحضــر املتهــم مــن‬\n‫الســجن وبســؤاله عمــا نســب إليــه أجــاب انكــر مــا نســب إلــي مــن ترويــج‬\n‫احلشــيش وأعتــرف بحيــازة نصــف حبــه مــن احلبــوب احملظــورة بقصــد‬\n‫التعاطــي والــذي حصــل أنــي أعمــل يف مطعــم بوظيفــة توصيــل طلبــات‬\n‫ويف يــوم احلــادث أتصــل علــي مديــري يف العمــل وطلــب منــي مفتــاح‬\n‫الســيارة فقلــت لــه أوصــل طلبــا وآتيــك وملــا رجعــت صعــدت إليــه يف شــقة‬\n‫يف الــدور الســادس احمللــق وعنــد البــاب وقبــل الدخــول جــاءت الفرقــة‬\n‫وألقــت القبــض علــي وإلحضــار البينــة رفعــت اجللســة ثــم حضــر الشــاهد‬\n‫‪....‬ســعودي مبوجــب الســجل املدنــي رقــم ‪ .........‬وقــرر بأنــه ال معلومــات‬\n‫لديــه وال شــهادة لديــه فيمــا يخــص هــذا املتهــم ثــم أحضــر املدعــي العــام‬\n‫للشــهادة وأدائها ‪ ....‬ســعودي مبوجب الســجل املدني رقم (‪ ).....‬وبســؤاله‬\n‫عمــا لديــه مــن شــهادة أجــاب الــذي يخصنــي منهــا أنــه وصلنــي مــن أحــد‬\n‫املصــادر الســرية عــن وجــود شــخص يدعــى يعمــل يف محــل بيتــزا ويقــوم‬\n‫بترويــج مــادة احلشــيش املخــدر وجــرى التنســيق معــه والشــراء منــه مببلــغ‬\n\n\n                                                                                     ‫‪274‬‬\n\f      ‫خمســمائة ريــال وجــرى االتصــال علــى جوالــه رقــم (‪ )....‬وقــال لــه املصــدر‬\n      ‫أبغــى حشــيش فقــال أنــا أوصــل طلبيــه ثــم أمــر البيــت وأجيبهــا لــك فقــال‬\n      ‫املصــدر أنتظــرك يف غرفتــي وكانــت املكاملــة حتــت ســماعي وعنــد‬\n      ‫محاولــة القبــض عليــه رمــى شــيئا كان بيــده أمــام أنظــار الفرقــة ومت‬\n      ‫القبــض عليــه وبتفتيشــه شــخصيا عثــر يف جيــب بنطلونــه علــى نصــف‬\n      ‫حبــه بيــج اللــون حتمــل عالمــة الكبتاجــون احملظــورة وبالتأكــد مــن‬\n      ‫الشــيء الــذي قــام برميــه اتضــح أنهــا قطعتــان ســوداوا اللــون بلــغ وزنهمــا‬\n      ‫إجمــا ًال (‪ )14,3‬يشــتبه أن تكــون مــن احلشــيش هــذا مــا لــدي مــن شــهادة‬\n      ‫وعليــه وبنــاء علــى الئحــة االتهــام والتــي انتهــى فيهــا التحقيــق إلــى توجيــه‬\n      ‫االتهــام إلــى ‪ .....‬يبلــغ مــن العمــر ‪ 30‬ســنة بحيــازة قطعتــن ســوداوين‬\n      ‫وزنهمــا أربعــة عشــر جرامـ ًا وثالثــة مــن عشــرة مــن اجلــرام بقصــد الترويــج‬\n      ‫وحيــازة نصــف حبــه مــن احلبــوب احملظــورة بقصــد التعاطــي ولكــون مــا‬\n      ‫أقــدم عليــه فعــل محــرم شــرعا ومعاقــب عليــه طلــب املدعــي العــام إثبــات‬\n      ‫مــا أســند إليــه واحلكــم عليــه وفــق املــادة (‪ )1/38‬واملــادة (‪ )1/56‬مــن‬\n      ‫نظــام مكافحــة املخــدرات وتشــديد العقوبــة عليــه لقــاء تعــدد ســوابقه‬\n      ‫املتكــررة وبنــاء علــى مــا أجــاب بــه املتهــم حيــث أنكــر مــا نســب‬\n      ‫إليــه مــن تهمــة الترويــج للحشــيش املخــدر وأقــر باحلضــور ملقــر ســكن‬\n      ‫املصــدر لعالقــة العمــل التــي تربطهمــا وبواقعــة القبــض عليــه كمــا أقــر‬\n      ‫بحيــازة حبــه محظــورة بقصــد التعاطــي وطلــب رد االتهــام املوجــه إليــه‬\n      ‫بخصــوص ترويــج احلشــيش املخــدر وبســؤال املدعــى العــام عــن إحضــار‬\n      ‫البينــة اكتفــى مبــا هــو مــدون يف الئحــة االتهــام ومــن ســمعت شــهادته‬\n      ‫أمــام احملكمــة وحيــث جــرى االطــاع علــى أقــوال املتهــم لــدى هيئــة‬\n      ‫التحقيــق واالدعــاء العــام فوجــدت ال تختلــف عمــا ذكــر أمــام احملكمــة‬\n\n\n‫‪275‬‬\n\f‫وحيــث جــرى االطــاع علــى احملضــر املعــد مــن قبــل رجــال مكافحــة‬\n‫املخــدرات وفيــه انــه رأوا املتهــم يرمــي بشــيء كان بيــده وتبــن أنهمــا‬\n‫قطعتــان مــن احلشــيش املخــدر وذلــك كلــه بنــاء علــى إخباريــة ان املتهــم‬\n‫يــروج احلشــيش املخــدر وعليــه مت متكــن املصــدر مــن االتصــال علــى‬\n‫اجلــوال اخلــاص باملــروج وطلــب منــه حشيشــا مخــدرا مببلــغ خمســمائة‬\n‫ريــال وكان ذلــك حتــت مســمع مــرأى أفــراد الفرقــة وعنــد مشــاهدة‬\n‫رجــال الفرقــة حــاول اإلفــات وضبــط يف جيــب بنطلــون نصــف حبــه مــن‬\n‫احلبــوب احملظــورة وقــد مت االســتماع إلــى الشــاهد ل الــذي شــهد طبــق‬\n‫مــا جــاء باحملضــر املعــد منــه ومــن زمالئــه واكتفــى املدعــي العــام بذلــك‬\n‫رغــم االســتدعاءات املتكــررة ومت االكتفــاء بشــهادتهم املدونــة يف‬\n‫احملضــر املعــد منهــم وحيــث أن جرميــة الترويــج البــد فيهــا مــن اكتمــال‬\n‫أركانهــا مــن االســتالم والتســليم ومشــاهدة كل ذلــك وثبــوت الركــن‬\n‫املعنــوي املعبــر عنــه بالقصــد اجلنائــي ومبــا أن هــذه اإلركان قــد تخلفــت‬\n‫فيبقــى األمــر املتيقــن بالنســبة لــه هــي احليــازة املجــردة ألنــه شــوهد وهــو‬\n‫يرمــي القطعــة ويعامــل علــى هذا األســاس الســيما وان املصــدر هو املدير‬\n‫املباشــر لــه يف عملــه فذهابــه إليــه لــه مــا يســوغه وإذا مــا تقــرر هــذا‬\n‫فالثابــت عليــه حيــازة حبــة محظــورة بقصــد التعاطــي وحيــازة مجــردة‬\n‫للحشــيش املخــدر واملــادة العقابيــة املنطبقــة عليــه هــي نــص املــادة (‪)39‬‬\n‫مــن نظــام املخــدرات وبالنســبة للحبــة احملظــورة بقصــد التعاطــي فتنــدرج‬\n‫عقوبتهــا يف العقوبــة األشــد طبقــا ملــا ســنذكره يف منطــوق احلكم وبناء‬\n‫علــى التقريــر الكيميائــي الشــرعي املرفــق بإيجابيــة عينــة مــا ضبــط‬\n‫للحشــيش املخــدر واحلبــوب املخــدرة ونظــرا لســوابق املتهــم من هــذا النوع‬\n‫مــن أجــل ذلــك حكمــت بإدانــة املتهــم بجرميــة احليــازة املجــردة للحشــيش‬\n\n\n                                                                                        ‫‪276‬‬\n\f      ‫املخــدر واحلكــم عليــه بالســجن ســنتني اعتبــارا مــن مدة توقيفــه وبغرامة‬\n      ‫مقدراهــا ثالثــة اآلف ريــال وبجلــده أربعــن جلــده تكــرر عليــه خمــس‬\n      ‫مــرات بينهــا عشــرة أيــام ومبنعــه مــن الســفر خــارج اململكــة ملــدة ســنتني‬\n      ‫بعــد تنفيــذ العقوبــة وبانــدراج عقوبــة حيازتــه لنصــف حبــه مــن احلبــوب‬\n      ‫احملظــورة يف العقوبــة األشــد وبإتــاف املــواد املخــدرة احملــرزة علــى ذمــة‬\n      ‫القضيــة بــذا صــدر احلكــم وافهــم حســب األصــول فقــرر املتهــم قناعتــه‬\n      ‫وقــرر املدعــي العــام االعتــراض بالئحــة وصلــى اهلل علــى ســيدنا ونبينــا‬\n                              ‫محمــد وعلــى الــه وصحبــه حــرر يف ‪1434/7/25‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد فقــد‬\n      ‫جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة اخلامســة مبحكمــة االســتئناف‬\n      ‫يف منطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن‬\n      ‫فضيلــة رئيــس احملكمــة اجلزائيــة باملدينــة املنــورة برقــم ‪332163323‬‬\n      ‫وتاريــخ ‪1434/9/8‬ه ـ املرفــق بهــا القــرار رقــم ‪ 34283200‬وتاريــخ‬\n      ‫‪1434/7/30‬ه ـ الصــادر مــن فضيلــة الشــيخ‪ ...........‬القاضــي باحملكمة‬\n      ‫اجلزائيــة باملدينــة املنــورة املتضمــن دعــوى املدعــي العــام ضــد ‪..............‬‬\n      ‫ســعودي اجلنســية املتهــم يف مخــدرات‪ ،‬احملكــوم فيــه مبــا دون بباطنــه‪،‬‬\n      ‫وبدراســة القــرار وصــورة ضبطــه والئحتــه االعتراضيــة قررنــا املوافقــة‬\n      ‫علــى احلكــم‪ ،‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                                      ‫وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪277‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c75d9efa-03f7-50be-835e-660792d35183","source_page_start":271,"source_page_end":277,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"f1654a37e4314163e06775f02b3a9e36c6913fcc1a52677b2ecb35a990e3d114","normalized_text_hash":"d17e3f78c885cc57cef65ddc60f2c05c6908d3c2090109028f08625fa4b13e93","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v20-p271-34283200"},{"id":"dc638b71-5fb9-592f-9be1-5de21063c1e6","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة بقصد التعاطي -قات -خلوة محرمة -التعزير بالسجن واجللد واإلبعاد عن الباد.","document_number":"3415883","case_number":"33689319","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/18","year":"1434","subject":"مخدرات -حيازة بقصد التعاطي -قات -خلوة محرمة -التعزير بالسجن واجللد واإلبعاد عن الباد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك‪ 3415883 :‬تاريخه‪1434/1/18 :‬هـ‬\n                   ‫رقم الدعوى‪33689319:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 3427932‬تاريخه‪1434/02/03 :‬هـ‬\n\n\n‫مخــدرات ‪ -‬حيــازة بقصــد التعاطــي ‪ -‬قــات ‪ -‬خلــوة محرمــة ‪ -‬التعزيــر‬\n                                  ‫بالســجن واجللــد واإلبعــاد عــن البــاد‪.‬‬\n\n\n\n\n                     ‫‪ -1‬قرار مجلس الوزراء رقم(‪ )11‬لعام ‪1374‬هـ ‪.‬‬\n ‫‪ -2‬املادة (‪ )4‬من قرار وزير الداخلية رقم ( ‪ ) 2057‬يف ‪1404/5/26‬هـ ‪.‬‬\n              ‫‪ -3‬قرار وزير الداخلية رقم (‪ )3818‬يف ‪1410/9/28‬هـ ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليهــا بحيــازة قــات بقصد االســتعمال‬\n‫الشــخصي وتســترها على مصدر ما مت ضبطه واخللوة احملرمة بشــخص‬\n‫أجنبــي عنهــا وطلــب إثبــات مــا أســند إليهــا واحلكــم بتعزيرهــا وإبعادهــا‬\n‫مــن البــاد بعــد انتهــاء محكوميتهــا ‪،‬حيــث شــاهد أعضــاء هيئــة‬\n‫األمــر باملعــروف والنهــي املنكــر ســيارة تقــف علــى جانــب الطريــق يف‬\n‫مــكان مظلــم واتضــح بأنهــا بقيــادة أحــد األشــخاص وبرفقتــه املدعــى‬\n‫عليهــا وهمــا بخلــوة محرمــة كمــا عثــر بحقيبــة املدعــى عليهــا كميــة‬\n‫مــن نبــات القــات فتــم القبــض عليهــا ‪ ،‬أثبــت التقريــر الكيميائــي‬\n‫الشــرعي إيجابيــة العينــة املضبوطــة لنبــات القــات احملظــور وصادقــت‬\n‫املدعــى عليهــا علــى االدعــاء املوجــه لهــا بحيــازة قــات بقصــد االســتعمال‬\n\n                                                                                    ‫‪278‬‬\n\f      ‫الشــخصي واخللــوة احملرمــة بشــخص أجنبــي عنهــا ‪،‬وبنــاء علــى مــا تقــدم‬\n      ‫حكمــت احملكمــة بتعزيرهــا بالســجن ثالثــة أشــهر وجلدهــا لقــاء‬\n      ‫ذلــك ولقــاء خلوتهــا مبائــة وخمســن جلــدة مفرقــة كل دفعــة قدرهــا‬\n      ‫خمســون جلــدة وإبعادهــا مــن البــاد بعــد إنفــاذ العقوبــة املقــررة بحقهــا و‬\n      ‫قنعــت املدعــى عليهــا باحلكــم واعتــرض املدعــي العــام مكتفيـ ًا بالئحــة‬\n                             ‫الدعــوى و صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بجــازان بنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بجــازان برقــم ‪ 33689319‬وتاريــخ ‪1433/12/19‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 332182905‬وتاريــخ ‪1433/12/19‬ه ـ ففــي يــوم‬\n      ‫الثالثاء املوافق‪1433/12/21‬هـ افتتحت اجللسة الساعة ‪ 09 : 15‬وفيها‬\n      ‫حضــر املدعــي العــام ‪.....‬بالتعميــد رقــم(‪ ).....‬وتاريــخ ‪1433/3/22‬ه ـ‬\n      ‫واملدعــى عليهــا ‪39(.....‬عام ـاً) مينيــة اجلنســية مبوجــب البطاقــة البديلــة‬\n      ‫رقــم(‪ ).....‬وتاريخ‪1433/11/9‬ه ـ الصــادرة مــن مكافحــة املخــدرات‬\n      ‫بصامطــة وقــدم املدعــي العــام دعــوى محــررة تتضمــن‪ :‬أنــه بتاريــخ‬\n      ‫‪1433/11/7‬ه ـ وأثنــاء قيــام أعضــاء هيئــة االمــر باملعــروف والنهــي عــن‬\n      ‫املنكــر بجولتهــم امليدانيــة مبحافظــة أحــد املســارحة شــوهدت ســيارة‬\n      ‫مــن نــوع رقــم اللوحــة ‪.....‬تقــف بجــوار طريــق قريــة ‪.....‬يف مــكان مظلــم‬\n      ‫واتضــح أنهــا بقيادة‪(.....‬وعائــدة ملكيتهــا ل ـ ‪.....‬لــم يوجــه لــه االتهــام)‬\n      ‫وبرفقتــه املدعــى عليهــا وهمــا يف خلــوة محرمــة وكان‪.....‬متعاطيـ ًا لنبات‬\n      ‫القــات احملظــور وبحوزتــه كميــة أخــرى مــن ذات النــوع تزن(‪50‬جــم)‬\n\n‫‪279‬‬\n\f‫خمســن جرامــا كمــا عثــر بحقيبــة املدعــى عليهــا كميــة مــن نبــات‬\n‫القــات احملظــور بلــغ وزنها(‪50‬جــم) خمســن جرامـ ًا فتــم القبــض عليهمــا‬\n‫أثبــت التقريــر الكيميائــي الشــرعي رقم(‪.....‬للعــام ‪1433‬هــ) إيجابيــة‬\n‫العينتــن املرســلتني منهمــا لنبــات القــات احملظــور وباطــاع أعضــاء هيئة‬\n‫األمــر باملعــروف علــى الهواتــف احملمولــة لــكل مــن املدعــى عليهــا و‪.....‬‬\n‫وجــدوا عــدة رســائل غراميــة مــن هاتــف املدعــى عليهــا إلــى هاتــف ‪.....‬‬\n‫وقــد أعــد بذلــك محضــر ًا ومبواجهتهــا بالتهمــة املنســوبة إليهــا وبأقوالهــا‬\n‫مبحضــر ســماع األقــوال أقــرت بــأن الكميــة املضبوطــة مــن نبــات القات‬\n‫احملظــور عائــدة لهــا وغرضهــا منهــا االســتعمال الشــخصي وأنــه حصلــت‬\n‫عليهــا دون مقابــل مــن شــخص ال تعرفــه وأنهــا كانــت راكبــة مع املدعو‬\n‫‪ .....‬لكــي يقــوم بإيصالهــا إلــى املستشــفى مقابــل أجــرة ماليــة وال تــدري‬\n‫كيــف ذهــب بهــا إلــى طريــق قريــة ‪.....‬وإنهــا ال تعلــم كيفيــة وصــول‬\n‫الرســائل مــن هاتفهــا إلــى هاتــف ‪ .....‬وصادقــت علــى أقوالهــا حتقيق ـ ًا‬\n‫وباســتجواب ‪.....‬ذكــر بأنــه املدعــى عليهــا طلبــت منــه إيصالهــا إلى قرية‬\n‫‪.....‬وليــس إلــى املستشــفى مقابــل أجــرة ماليــة وأنــه لــم يتوقــف بجانــب‬\n‫الطريــق بــل إن أعضــاء هيئــة األمــر باملعــروف هــم مــن اســتوقفوه أثنــاء‬\n‫ســيره بالســيارة (فــرزت لــه أوراق مســتقلة إلقامــة الدعــوى العامــة عليــه‬\n‫مبــكان إقامتــه كونــه مفــرج عنــه) وأســفر التحقيــق عــن توجيــه االتهام‬\n‫إليهــا بحيازتهــا مــا وزنــه (‪50‬جــم) خمســون جرام ـ ًا مــن نبــات القــات‬\n‫احملظــور بقصــد االســتعمال الشــخصي وتســترها علــى مصــدر مــا مت‬\n‫ضبطــه وباخللــوة احملرمــة شــرع ًا بشــخص ال ميــت لهــا بصلــة وذلــك لألدلــة‬\n‫والقرائــن التاليــة‪/1 :‬مــا جــاء يف أقوالهــا حتقيق ـ ًا املنــوه عنهــا املرفقــة‬\n‫لفــه (‪/2 )11‬مــا جــاء مبحضــر القبــض املرفــق لفــه رقــم (‪/3 )2‬مــا ورد‬\n\n\n                                                                                       ‫‪280‬‬\n\f      ‫بالتقريــر الكيميائــي الشــرعي املنــوه عنــه املرفــق لفــه (‪ /4 )10‬مــا جــاء‬\n      ‫بحضــر معاينــة الهواتــف احملمولــة املعــد مــن قبــل أعضــاء هيئــة األمــر‬\n      ‫باملعــروف املنــوه عنــه املرفــق لفــه (‪ )3‬والــذي يعــد قرينــة علــى عالقتهمــا‬\n      ‫املســبقة ببعضهمــا ‪ /5‬تناقــض أقوالهمــا حيــث ذكــر املدعــى عليــه بأنــه‬\n      ‫يريــد إيصالهــا إلــى قريــة ‪.....‬وناقضــت ذلــك بانهــا تريــد منــه إيصالهــا‬\n      ‫إلــى املستشــفى ممــا يعــد علــى عالقتهمــا احملرمــة مســبق ًا وبالبحــث عــن‬\n      ‫ســوابقها لــم يعثــر لهــا علــى ســوابق جنائيــة مســجلة وحيــث إن مــا أقدمــت‬\n      ‫عليــه املدعــى عليهــا فعــل محــرم شــرع ًا ومعاقــب عليــه نظام ـ ًا مبوجــب‬\n      ‫قــرار مجلــس الــوزراء رقــم (‪ )11‬لعام‪1374‬ه ـ ومــا حلــق بــه تعديــات لــذا‬\n      ‫أطلــب مــا يلــي‪/1 :‬إثبــات إدانتهــا مبــا اســند إليهــا واحلكــم بتعزيرهــا‬\n      ‫يف ضــوء املــادة (الرابعــة) مــن القــرار املشــار إليــه أعــاه إنفــاذ ًا لألمــر‬\n      ‫الســامي الكــرمي رقــم (‪ )59633‬وتاريخ‪1432/12/9‬ه ـ ‪/2‬احلكــم‬\n      ‫بإبعادهــا عــن البــاد بعــد انتهــاء محكوميتهــا اســتنادا للقــرار الــوزاري‬\n      ‫املشــار إليــه أعــاه ‪ /3‬احلكــم بتعزيرهــا شــرع ًا لقــاء تســترها علــى‬\n      ‫مصــدر مــا مت ضبطــه احلكــم بتعزيرهــا شــرع ًا ‪ /4‬احلكــم بتعزيرهــا‬\n      ‫شــرع ًا لقــاء خلوتهــا برجــل ال ميــت لهــا بصلــة شــرعية وبســؤال املدعــى‬\n      ‫عليهــا ‪ .....‬مينيــة اجلنســية أجابــت باالعتــراف بحيــازة مــا وزنــه خمســون‬\n      ‫جرامـ ًا مــن نبــات القــات احملظــور لقصــد االســتعمال الشــخصي واخللــوة‬\n      ‫احملرمــة مــع شــخص ال ميــت لهــا بصلــة شــرعية هكــذا أجابــت عنــد‬\n      ‫ذلــك جــرى منــا االطــاع علــى التقريــر الشــرعي وعلــى محضــري الــوزن‬\n      ‫ـاء علــى‬‫والقبــض فوجــدت مطابقــة ملــا جــاء بدعــوى املدعــي العــام وبنـ ً‬\n      ‫مــا ذكــر مــن دعــوى املدعــي العــام وعلــى إجابــة املدعــى عليهــا ‪ .....‬مينيــة‬\n      ‫اجلنســية باالعتــراف بحيــازة مــا وزنــه خمســون جرام ـ ًا مــن نبــات القــات‬\n\n\n‫‪281‬‬\n\f‫احملظــور لقصــد االســتعمال الشــخصي واخللــوة احملرمــة مــع شــخص ال‬\n‫ميــت لهــا بصلــة شــرعية لــذا فقــد ثبــت لــدي شــرع ًا إدانــة املدعــى عليهــا‬\n‫املذكــور بحيــازة كميــة القــات احملظــور لقصــد االســتعمال الشــخصي‬\n‫واخللــوة احملرمــة مــع شــخص ركبــت معــه وهــو ال ميــت لهــا بصلــة شــرعية‬\n‫وهــي تســتحق العقوبــة علــى ذلــك وفــق املــادة الرابعــة مــن قــرار وزيــر‬\n‫الداخليــة رقــم (‪ )2057‬وتاريخ‪1404/5/26‬ه ـ املعــدل بالقــرار الــوزاري‬\n‫رقــم (‪ )3818‬وتاريــخ ‪1410/9/28‬ه ـ اســتنادا لقــرار مجلــس الــوزراء‬\n‫رقــم (‪ )11‬وتاريــخ ‪1432/12/1‬ه ـ وملــا ذكــر أعــاه ولعــدم وجــود‬\n‫ســوابق علــى املدعــى عليهــا وكونهــا وافــدة ســترحل عــن البــاد بعــد‬\n‫إنفــاذ العقوبــة املقــررة بحقهــا شــرع ًا وال فائــدة ترجــى مــن طــول ســجنها‬\n‫ولضآلــة كميــة نبــات القــات احملظــور املضبــوط بحوزتهــا لالســتعمال‬\n‫لــذا فقــد حكمــت بتعزيــر املدعــى عليهــا املذكــورة بالســجن ملــدة‬\n‫ثالثــة أشــهر مــن تاريــخ إيقافهــا علــى ذمــة القضيــة يف ‪1433/11/7‬ه ـ‬\n‫وجلدهــا لقــاء ذلــك ولقــاء اخللــوة احملرمــة مــع الشــخص املوضــح أعــاه‬\n‫مبائــة وخمســن جلــدة علن ـ ًا مفرقــة كل دفعــة خمســون جلــدة بــن‬\n‫الدفعــة واألخــرى عشــرة أيــام وإبعادهــا عــن البــاد بعــد انفــاذ العقوبــة‬\n‫املقــررة بحقــه شــرع ًا هــذا مــا حكمــت بــه وبعرضــه علــى الطرفــن‬\n‫قــررت املدعــى عليهــا القناعــة وطلــب املدعــي العــام اســتئناف احلكــم‬\n‫مكتفيـ ًا بالئحــة االدعــاء العــام وأمــرت بتنظيــم القــرار الــازم مبوجبــه‬\n‫ورفعــه حملكمــة االســتئناف مبنطقــة عســير لدراســته وإبــداء مــا تــراه‬\n‫نحــوه وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف‬\n                                                               ‫‪1433/12/21‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة لتدقيــق‬\n\n\n                                                                                       ‫‪282‬‬\n\f      ‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n      ‫الــواردة مــن فضيلــة رئيــس احملكمة اجلزائية بجــازان رقم ‪332182905‬‬\n      ‫وتاريــخ ‪1434/1/19‬ه ـ املرفــق بهــا القــرار الشــرعي الصــادر مــن فضيلة‬\n      ‫الشــيخ‪..... /‬رقــم ‪ 3415883‬وتاريــخ ‪1434/1/18‬ه ـ اخلــاص بدعــوى‬\n      ‫املدعــي العــام ضــد‪ (..... /‬مينيــة اجلنســية ) يف قضيــة ( خلــوه غيــر شــرعيه‬\n      ‫وحيــازة نبــات القــات ) علــى الصفــة املوضحــة يف القــرار املتضمــن حكم‬\n      ‫فضيلتــه مبــا هــو مــدون ومفصــل فيــه وبدراســة القــرار وصــورة ضبطــه‬\n      ‫وأوراق املعاملــة تقــررت املوافقــة علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل‬\n                                        ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪283‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c75d9efa-03f7-50be-835e-660792d35183","source_page_start":278,"source_page_end":283,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b4039482fa2a4a08277f28055a086f9c2dc97f0d040f2f2e023120211ceae168","normalized_text_hash":"625579d16845f0322fbde4b9a93286fadff866e9ef9757a0f1183fbb482a0e60","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v20-p278-3415883"},{"id":"cc3ea44b-4b72-50a0-8a36-40efbbca5c01","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حشيش بقصد الترويج -إثبات بالشهادة -إدانة باحليازة املجردة عن القصد -تعزير بالسجن واجللد والغرامة واملنع من السفر.","document_number":"34178295","case_number":"33696919","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف باألكثرية املوافقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/12/21","year":"1434","subject":"مخدرات -حيازة حشيش بقصد الترويج -إثبات بالشهادة -إدانة باحليازة املجردة عن القصد -تعزير بالسجن واجللد والغرامة واملنع من السفر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34178295:‬تاريخه ‪1433/12/21:‬هـ‬\n                   ‫رقم الدعوى ‪33696919:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34228392‬تاريخه‪1434/06/03:‬هـ‬\n\n\n‫مخــدرات‪ -‬حيــازة حشــيش بقصــد الترويــج‪ -‬إثبــات بالشــهادة‪ -‬إدانــة‬\n‫باحليــازة املجــردة عــن القصــد‪ -‬تعزيــر بالســجن واجللــد والغرامــة‬\n                                                    ‫واملنــع مــن الســفر‪.‬‬\n\n\n\n\n     ‫املادتان (‪ )39‬و(‪ )56‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n\n\n\n\n‫دعــوى جزائيــة عامــة ضــد املدعــى عليــه تتضمــن طلــب إثبــات إدانتــه‬\n‫بحيــازة احلشــيش املخــدر بقصــد الترويــج ‪ ،‬واحلكــم عليــه بعقوبــة‬\n‫الســجن واجللــد والغرامــة واملنــع مــن الســفر طبقــا لنظــام مكافحــة‬\n‫املخــدرات واملؤثــرات العقليــة‪ ،‬بعــد إحضــاره مــن الســجن إلــى احملكمــة‬\n‫شــوهد وهــو يخــرج مــن حتــت بــاب الطــوارئ بالونــات بهــا قطــع مــن‬\n‫احلشــيش‪،‬أثبت التقريــر الكيميائــي الشــرعي إيجابيــة العينــة املرســلة‬\n‫للحشــيش املخــدر‪ ،‬أنكــر أمــام احملكمــة مــا أســنده إليــه املدعــي‬\n‫العــام‪ ،‬طلبــت احملكمــة مــن املدعــي العــام تقــدمي بيناتــه وقــررت ســماع‬\n‫شــهادة شــهود محضــر القبــض فشــهدوا مبــا يثبــت دعــوى املدعــي العــام‬\n‫ســوى قصــد الترويــج مــن احليــازة‪ ،‬قضــت احملكمــة بإدانــة املدعــى عليــه‬\n‫بحيــازة احلشــيش املخــدر حيــازة مجــردة وقــررت ســجنه ملــدة ســنتني‬\n\n                                                                                  ‫‪284‬‬\n\f      ‫وجلــده علنــا مائــة وخمســن جلــدة وتغرميــه مبلــغ ثالثــة آالف ريــال ومنعــه‬\n      ‫مــن الســفر خــارج اململكــة ملــدة ســنتني‪ ،‬عــارض املدعــى عليــه واملدعــي‬\n      ‫العــام علــى احلكــم‪ ،‬قــررت محكمــة االســتئناف باألكثريــة املوافقــة‬\n                                                                       ‫علــى احلكــم‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا‪ ....‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫باملدينــة املنــورة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة اجلزائيــة باملدينــة املنــورة برقــم ‪ 33696919‬وتاريــخ‬\n      ‫‪1433/12/21‬ه ـ املقيــدة باحملكمــة برقــم ‪ 332211901‬وتاريــخ‬\n      ‫‪1433/12/21‬ه ـ واملتعلقــة بدعــوى املدعــي العــام ضــد املدعــى عليــه ‪....‬‬\n      ‫ســعودي بالســجل املدنــي رقــم (‪ )000‬يســكن ‪ .....‬حــي ‪ .....‬متهــم بحيــازة‬\n      ‫نباتــات محظــورة بقصــد الترويــج مبقابــل موقــوف بســجن املدينــة بذمــة‬\n      ‫قضيــة أخــرى‪ ،‬عليــه ففــي هــذا اليــوم األحــد ‪1434/01/04‬ه ـ افتتحــت‬\n      ‫اجللســة الواحــدة ظهــر ًا وفيهــا حضــر الطرفــان فادعــى املدعــي العــام‬\n      ‫ا يف دعــواه‪ :‬إنــه باالطــاع علــى محضــر القبــض املعــد مــن قبــل‬          ‫قائ ـ ً‬\n      ‫شــعبة الســجن العــام باملدينــة املنــورة بتاريــخ ‪1433/10/29‬ه ـ املتضمــن‬\n      ‫أنــه بعــد إحضــار الســجناء إلــى احملكمــة اجلزئيــة باملدينــة املنــورة‬\n      ‫وداخــل احملكمــة شــاهدوا الســجني املتهــم املذكــور يخــرج مــن حتــت‬\n      ‫بــاب الطــوارئ بالونــات وبضبطهــا اتضــح أن عددها(‪)22‬حبــة حتتــوي‬\n      ‫علــى قطــع بلــغ وزنهــا اإلجمالي(‪)72,2‬جــم يشــتبه أن تكــون حشــيش‬\n      ‫مخــدر وقــد مت إيقــاف املتهــم يف الســجن العــام باملدينــة املنــورة اســتناد ًا‬\n      ‫إلــى الفقــرة الرابعــة مــن القــرار الــوزاري رقم‪1900‬وتاريــخ ‪1428/7/9‬هـ‬\n\n‫‪285‬‬\n\f‫املبنــي علــى املــادة (‪ )112‬مــن نظــام اإلجــراءات اجلزائيــة مبوجــب أمــر‬\n‫متديــد توقيــف رقــم(‪ )39051‬وتاريــخ ‪1433/11/ 17‬ه ـ وباســتجوابه‬\n‫بعــد إحاطتــه بالتهمــة املوجهــة إليــه واجلهــة التــي تقــوم بالتحقيــق معــه‬\n‫أنكــر حيــازة مــا مت ضبطــه مــن حشــيش مخــدر وقــد أثبــت التقريــر‬\n‫الكيميائــي الشــرعي رقــم(‪2372‬ك م) لعام‪1433‬ه ـ الصــادر مــن‬\n‫مركــز الســموم والكيميــاء الشــرعية التابــع لــوزارة الصحــة باملنطقــة‬\n‫املدينــة املنــورة إيجابيــة عينــة مــا مت ضبطــه للقنــب (احلشــيش املخــدر)‬\n‫وهــو مــن املــواد املخــدرة اخلاضعــة للرقابــة يف اجلــدول األول فئــة (أ) وهــو‬\n‫مــن اجلــداول امللحقــة بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة‬\n‫الصــادر باملرســوم امللكــي رقــم‪ 39/‬وتاريــخ ‪1426/7/8‬هــ‪ ،‬وانتهــى‬\n‫التحقيــق إلــى اتهامــه بحيــازة (‪ )72,2‬اثنــي وســبعون وعشــري اجلــرام‬\n‫بقصــد الترويــج‪ ،‬واملجــرم ذلــك مبقتضــى املــادة الثالثــة الفقــرة الثانيــة‬\n‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة املشــار إليــه بعاليــه‬\n‫وذلــك لألدلــة والقرائــن التاليــة‪ )1 :‬مــا ورد يف محضــري القبــض (لفــة‪-1‬‬\n‫‪/2،)2‬مــا ورد يف إفــادة رجــال الضبــط املدونــة علــى الصفحــة رقــم (‪)3‬‬\n‫مــن دفتــر التحقيــق لفــة (‪/3،)11‬التقريــر الكيميائــي الشــرعي رقــم‬\n‫(‪2372‬ك م) لعام‪1433‬ه ـ (لفــة‪ )13‬وحيــث إن مــا أقــدم عليــه املذكــور‬\n‫فعــل محــرم ومعاقــب عليــه شــرع ًا ونظامـ ًا ‪ ،‬لــذا أطلــب إثبــات إدانتــه مبــا‬\n‫أســند إليــه واحلكــم عليــه باآلتــي‪/1 :‬عقوبــة الســجن واجللــد والغرامــة‬\n‫اســتناد ًا للمــادة(‪ )38‬الفقــرة األولى‪/2،‬عقوبــة املنــع مــن الســفر خــارج‬\n‫البــاد التكميليــة للمــادة رقــم (‪ )56‬الفقــرة األولــى وذلــك مبقتضــى‬\n‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة املشــار إليــه هكــذا‬\n‫ادعــى املدعــي العــام‪ ،‬وبســؤال املدعــى عليــه عــن دعــوى املدعــي العــام‬\n\n\n                                                                                        ‫‪286‬‬\n\f      ‫ضــده أجــاب قائــا‪ :‬مــا ذكــره املدعــي العــام ضــدي غيــر صحيــح‪،‬‬\n      ‫والواقــع حيــث إننــي كنــت يف غرفــة االنتظــار يف احملكمــة فشــاهدت‬\n      ‫البالونــات املذكــورة يف األرض فحملــت واحــدة منهــا وســالت عنهــا‬\n      ‫اجلالــس بجانبــي‪ ،‬ويف هــذه األثنــاء دخــل العســكري واتهموني بحيازتها‬\n      ‫وهــذا غيــر صحيــح حيــث إننــي ال أعلــم عنهــا شــيئ ًا لــم أتعــاط مــن احلبوب‬\n      ‫احملظــورة والســوابق املســجلة ضــدي صحيحــة هكــذا أجــاب فســألت‬\n      ‫املدعــي العــام هــل لديــه بينــة علــى مــا ادعــاه ونفــاه املدعــى عليــه فقــال‪:‬‬\n      ‫لــدي بينــة وأطلــب مهلــة إلحضارهــا هكــذا قــال‪ ،‬ثــم أحضــر املدعــي‬\n      ‫العــام الشــاهد ‪....‬ســعودي اجلنســية بالســجل املدنــي رقــم‪ ....‬وباستشــهاده‬\n      ‫شــهد قائ ـاً‪ :‬أشــهد هلل أنــه أثنــاء عملــي يف حراســة الســجناء يف‬\n      ‫احملكمــة وأثنــاء دخولــي صالــة انتظــار الســجناء شــاهدت املدعــى عليــه‬\n      ‫جالسـ ًا علــى األرض عنــد بــاب الطــوارئ وهــو يســحب بالونــات مــن حتــت‬\n      ‫البــاب ويقــوم املدعــى عليــه بســحبها مــن حتــت البــاب ولــم تكــن مرميــة‬\n      ‫أمــام البــاب وشــاهدت املدعــى عليــه يحملهــا يف يــده فتــم ضبطــه وضبــط‬\n      ‫البالونــات واتضــح أن بهــا مــادة احلشــيش املخــدر وقــد أنكــر املدعــى‬\n      ‫عليــه عالقتــه بهــا هــذا مــا لــدي وبــه أشــهد هكــذا شــهد املذكــور‬\n      ‫كمــا أحضــر الشــاهدين ‪....‬ســعودي اجلنســية بالســجل املدنــي رقــم‪....‬‬\n      ‫و‪ ....‬ســعودي اجلنســية بالســجل املدنــي رقــم‪ ....‬وباستشــهادهما شــهد‬\n      ‫كل واحــد منهمــا قائـاً‪ :‬أشــهد هلل أننــي دخلــت صالــة انتظــار الســجناء‬\n      ‫يف احملكمــة بعــد طلــب رئيســي منــي ذلــك فشــاهدت املدعــى عليــه‬\n      ‫جالس ـ ًا علــى األرض ومعــه بالونــات فيهــا مــادة احلشــيش املخــدر وأثنــاء‬\n      ‫دخولنــا شــاهدته يرميهــا علــى األرض علم ـ ًا أن هــذه البالونــات كانــت‬\n      ‫خلــف بــاب الطــوارئ وليــس أمامــه هــذا مــا لــدي وبه أشــهد هكذا شــهد‬\n\n\n‫‪287‬‬\n\f‫املذكــوران وبعــرض مــا جــاء يف شــهادة الشــهود علــى املدعــى عليــه قــال‪:‬‬\n‫مــا ذكــره الشــهود غيــر صحيــح والصحيــح مــا ذكرتــه يف جوابــي وأمــا‬\n‫الشــهود فــا أقــدح فيهــم بشــيء ولكنهــم شــهدوا ضــدي حتــى يخلــوا‬\n‫مســؤوليتهم يف وجــود املــواد املخــدرة يف املــكان املكلفــن بحراســته‬\n‫وليــس بينــي وبينهــم أي عــداوة هكــذا قــال‪ .‬فطلبــت مــن املدعــي العــام‬\n‫ال مــن ســعودي اجلنســية‬  ‫تزكيــة شــهوده فأحضــر مزكيــن لشــهوده ك ً‬\n‫بالســجل املدنــي رقــم (‪ )....‬واملدعــو ‪....‬ســعودي اجلنســية بالســجل املدنــي‬\n‫رقــم (‪ )....‬فشــهد كل واحــد منهمــا منفــرد ًا قائ ـاً‪ :‬أشــهد هلل تعالــى‬\n‫أننــي أعــرف الشــهود و‪ ....‬و‪ ....‬وأشــهد هلل أنهــم ثقــات عــدول هكــذا‬\n‫شــهد كل واحــد منهمــا ‪ ،‬فجــرى منــي دراســة أوراق املعاملــة فوجــدت‬\n‫مــن ضمنهــا محضــر الضبــط املــؤرخ يف ‪1433/10/29‬ه ـ املتضمــن نحــو‬\n‫مــا ذكــره املدعــي العــام يف دعــواه ‪ ،‬كمــا وجــدت التقريــر الكيميائــي‬\n‫الشــرعي رقــم ‪ 2372‬يف ‪1433/11/8‬ه ـ املتضمــن إيجابيــة مــا مت ضبطه‬\n‫ـاء علــى مــا‬\n             ‫يف هــذه القضيــة للحشــيش املخــدر انتهــى مضمونــه ‪ ،‬فبنـ ً‬\n‫تقــدم مــن الدعــوى واإلجابــة وبعــد االطــاع علــى أوراق املعاملــة وحيــث‬\n‫ـاء علــى‬\n        ‫أنكــر املدعــى عليــه مــا جــاء يف دعــوى املدعــي العــام ضــده وبنـ ً‬\n‫مــا جــاء يف شــهادة الشــهود املذكــورة بعاليــه ومــا جــاء يف محضــر‬\n‫الضبــط وحيــث لــم يــرد يف شــهادة الشــهود وال يف أوراق املعاملــة مــا‬\n‫يــدل علــى أن قصــد املدعــى عليــه مــن حيــازة الكميــة املضبوطــة معــه‬\n‫الترويــج ولــم يعتــرف املدعــى عليــه بقصــده مــن حيازتهــا ونظــر ًا النطبــاق‬\n‫مــا أديــن بــه املدعــى عليــه علــى الوصــف اجلرمــي الــوارد يف املــادة التاســعة‬\n‫والثالثــن مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ولــذا فقــد‬\n‫ثبــت لــدي إدانــة املدعــى عليــه بحيــازة اثنــن وســبعني جرامـ ًا واثنــن مــن‬\n\n\n                                                                                         ‫‪288‬‬\n\f      ‫العشــرة مــن اجلــرام مــن احلشــيش املخــدر لغيــر قصــد االجتــار أو الترويــج‬\n      ‫أو االســتعمال الشــخصي ‪ ،‬ولــم يثبــت لــدي إدانتــه بقصــد الترويــج مــن‬\n      ‫حيازتهــا ‪ ،‬ونظــر ًا لوجــود ســابقة مســجلة ضــد املدعــى عليــه يف حيــازة‬\n      ‫املخــدرات فقــد حكمــت علــى املدعــى عليــه تعزيــر ًا يف احلــق العــام مبــا‬\n      ‫يلــي‪ :‬حكمــت بســجنه ســنتني حتتســب منهــا فتــرة إيقافــه علــى ذمــة هذه‬\n      ‫القضية وجلده علن ًا مائة وخمســن جلدة مفرقة على ثالث فترات كل‬\n      ‫فتــرة خمســون جلــدة وبــن كل فترتــن مــا ال يقــل عن خمســة عشــر يوم ًا‬\n      ‫وتغرميــه مبلــغ ثالثــة آالف ريــال اســتناد ًا للمــادة التاســعة والثالثــن مــن‬\n      ‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ‪ ،‬وحكمــت بــرد دعــوى‬\n      ‫املدعــي العــام بطلبــه مجــازاة املدعــى عليــه بالعقوبــات الــواردة يف املــادة‬\n      ‫الثامنــة والثالثــن مــن ذات النظــام لعــدم ثبــوت إدانتــه بقصــد الترويــج يف‬\n      ‫حيــازة الكميــة املضبوطــة معــه‪ .‬ثانيـاً‪ :‬حكمــت مبنعــه من الســفر خارج‬\n      ‫اململكــة ملــدة ســنتني بعــد انتهــاء محكوميتــه اســتناد ًا للمــادة السادســة‬\n      ‫واخلمســن مــن ذات النظــام وبذلــك حكمــت ‪ ،‬وبعرضــه علــى املدعــى‬\n      ‫عليــه واملدعــي العــام قــررا االعتــراض علــى احلكــم بالئحــة اعتراضيــة‬\n      ‫فجــرى تســليم كل واحــد منهمــا نســخة مــن احلكــم وأفهمتهمــا بــأن‬\n      ‫لهمــا تقــدمي االعتــراض علــى احلكــم يف مــدة أقصاهــا ثالثــون يومـ ًا مــن‬\n      ‫تاريــخ اســتالم نســخة احلكــم وإذا انتهــت املــدة ولــم يقدمــا االعتــراض‬\n      ‫ســيرفع احلكــم حملكمــة االســتئناف خــال خمســة وأربعــن يوم ـ ًا مــن‬\n      ‫تاريــخ النطــق باحلكــم ففهمــا ذلــك وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                      ‫آلــه وصحبــه وســلم حــرر يف ‪1434/04/03‬هــ‪.‬‬\n      ‫احلمــد اهلل والصــاة والســام علــى رســول اهلل وبعــد ‪ ...‬نحــن رئيــس‬\n      ‫وقضــاة الدائــرة اجلزائيــة الرابعــة يف محكمــة االســتئناف مبنطقة مكة‬\n\n\n‫‪289‬‬\n\f‫املكرمــة جــرى منــا االطــاع علــى القــرار رقــم ‪ 34178295‬وتاريــخ‬\n‫‪1434/04/03‬ه ـ الصــادر مــن فضيلــة الشــيخ‪ ....‬القاضــي باحملكمــة‬\n‫اجلزائيــة باملدينــة املنــورة‪ ،‬املتضمــن دعــوى املدعــى العــام ضــد‪ ، ....‬املتهــم‬\n‫بحيــازة مخــدرات‪ ،‬احملكــوم فيــه مبــا دون باطنــه‪ .‬وبدراســة القــرار‬\n‫وصــورة ضبطــه والالئحــة االعتراضيــة تقــرر باألكثريــة املوافقــة علــى‬\n‫احلكــم‪ ،‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                                               ‫وســلم‪.‬‬\n\n\n\n\n                                                                                         ‫‪290‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c75d9efa-03f7-50be-835e-660792d35183","source_page_start":284,"source_page_end":290,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"5c3055d9172ef58cba04019781a87c3b58354bfb7889a34b04eb3f7714930152","normalized_text_hash":"a23bbf7d5a70da1b0deacf8a45d3c606fa113e995c66bb65e088cd8df0e74665","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v20-p284-34178295"}]$archive_payload$::jsonb AS data)
INSERT INTO public.legal_documents (
  id,document_type,category,subcategory,title,document_number,case_number,judgment_number,decision_number,
  circular_number,court,circuit,issuing_authority,document_date,hijri_date,year,subject,summary,facts,claims,
  reasoning,ruling,principle_text,full_text,legal_articles,source_id,source_file_id,source_page_start,
  source_page_end,original_source,acquisition_source,source_url,content_hash,normalized_text_hash,status,review_status
)
SELECT (x->>'id')::uuid,x->>'document_type',x->>'category',x->>'subcategory',x->>'title',x->>'document_number',
       x->>'case_number',x->>'judgment_number',x->>'decision_number',x->>'circular_number',x->>'court',x->>'circuit',
       x->>'issuing_authority',(x->>'document_date')::date,x->>'hijri_date',x->>'year',x->>'subject',x->>'summary',
       x->>'facts',x->>'claims',x->>'reasoning',x->>'ruling',x->>'principle_text',x->>'full_text',
       COALESCE(x->'legal_articles','[]'::jsonb),(x->>'source_id')::uuid,(x->>'source_file_id')::uuid,
       (x->>'source_page_start')::integer,(x->>'source_page_end')::integer,x->>'original_source',
       x->>'acquisition_source',x->>'source_url',x->>'content_hash',x->>'normalized_text_hash',x->>'status',x->>'review_status'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT (id) DO NOTHING;

